   where master_session_id=(p_request->>''master_session_id'')::uuid for update;
 perform 1 from public.master_v2_sessions where id=(p_request->>''master_session_id'')::uuid for update;
 select * into strict w from mission_generic_owner.work_items where master_session_id=(p_request->>''master_session_id'')::uuid
 and event_id=(p_request->>''event_id'')::uuid and request_key=(p_request->>''request_key'')::uuid and revision=(p_request->>''expected_revision'')::bigint for update;
 if mission_generic_owner.count_overflow_terminal_v1(w.id,p_user) then return jsonb_build_object(''state'',''failed'',''granted_now'',false);end if;
 campaign_scope:=NOT EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=w.master_session_id) AND (EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 sticky_wc
 WHERE sticky_wc.master_session_id=w.master_session_id AND sticky_wc.scope=''staff_mission''
 AND sticky_wc.contract_sha256=public.combat_v2_sha256(sticky_wc.contract)
 AND sticky_wc.contract->>''schema_version''=''mission-narrative-admission/3''
 AND sticky_wc.contract->''features'' ? ''execution_authority_v1''
 AND (sticky_wc.contract#>>''{source_attestation,execution_authority,schema_version}''=''c1266-work-execution-attestation/1'' OR ((mission_generic_owner.c1266_historical_work_v1(sticky_wc.work_id)->>''schema_version''=''c1266-work-execution-attestation/2'') AND sticky_wc.contract#>''{source_attestation,execution_authority}''=mission_generic_owner.c1266_historical_work_v1(sticky_wc.work_id)))
 AND sticky_wc.contract#>>''{source_attestation,execution_authority,execution_context}''=''staff_mission''
