 WHERE NOT EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 manual_source WHERE manual_source.master_session_id=bs21.master_session_id) AND bs21.master_session_id=w.master_session_id
 AND ms21.owner_kind=''ai_service'' AND ms21.master_user IS NULL
 AND ms21.location_id=''0b85f354-9cdb-47e1-baf9-3d266bb7e06b''::uuid
 AND (ss21.source_mission_id=''5878822d-dc03-4ac2-ad0b-1547f0ab3fc0''::uuid OR (mission_generic_owner.c1266_staff_source_scope_v1(bs21.master_session_id) IS NOT NULL AND ss21.source_mission_id::text=mission_generic_owner.c1266_staff_source_scope_v1(bs21.master_session_id)#>>''{source_scope,mission_id}''))
 AND sc22.state=''bound'' AND sc22.simulation
 AND sc22.mission_id=ms21.mission_id AND sc22.location_id=ms21.location_id
 AND sc22.request_key=bs21.request_key
 AND bs21.simulation AND bs21.snapshot->''simulation''=''true''::jsonb
 AND bs21.snapshot_sha256=mission_internal.fingerprint(bs21.snapshot)
 AND bs21.snapshot->>''schema_version''=''mission-generic-opening-source/1''
 AND bs21.snapshot->>''mission_id''=ss21.carrier_mission_id::text
 AND bs21.snapshot->>''location_id''=''0b85f354-9cdb-47e1-baf9-3d266bb7e06b''
 AND rb21.snapshot_sha256=mission_internal.fingerprint(rb21.snapshot)
 AND rb21.snapshot->>''schema_version''=''mission-generic-run/1''));
 IF campaign_scope AND((w.state=''claimed'' AND w.lease_expires_at<=clock_timestamp()) OR(w.state=''ready'' AND w.dispatch_receipt_id IS NOT NULL)) THEN
  observed:=public.mission_generic_dispatch_status_v1(p_user,p_request);
  SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=w.id;
  RETURN jsonb_build_object(''state'',w.state,''granted_now'',false,''reason_code'',CASE WHEN w.state IN(''failed'',''completed'') THEN ''C1266_CAMPAIGN_TERMINAL_NO_REISSUE'' ELSE ''C1266_CAMPAIGN_RECOVERY_PENDING'' END);
 END IF;
 if w.state=''claimed'' and w.master_session_id=''ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9''::uuid AND (w.id<>''48e1bdcd-f044-be8c-1923-54d38e7e822c''::uuid OR w.lease_expires_at IS NULL OR w.lease_expires_at>clock_timestamp()) then return jsonb_build_object(''state'',''claimed'',''granted_now'',false);end if;
 IF w.id=''48e1bdcd-f044-be8c-1923-54d38e7e822c''::uuid AND (mission_generic_owner.c8_context24_scope_v1(w.id) IS DISTINCT FROM TRUE OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) IS DISTINCT FROM TRUE) THEN RAISE EXCEPTION ''C889_CONTEXT24_RUNTIME_CLOSED'' USING ERRCODE=''42501'';END IF;
 perform mission_generic_owner.role_dispatch_assert_v4(w.id);
 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) THEN
  c5_proof:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
  IF c5_proof IS NULL OR mission_generic_owner.flow_scope_enabled(w.master_session_id) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION ''C1266_CLAIM5_CLOSED'' USING ERRCODE=''42501'';END IF;
 END IF;
 c26_proof:=mission_generic_owner.c1266_clean_staff_admission_v1(w.master_session_id,true,true);
 named_clean48:=((mission_factory_owner.keys_exact_v2(c26_proof,ARRAY[''schema_version'',''policy'',''admission_attestation'',''finite_admission_sha256'',''release_sha256'',''binding_sha256'',''c7_budget_qualification_sha256'',''c8_count_qualification_sha256'']) AND c26_proof->>''schema_version''=''c1266-clean-staff-admission/1'' AND ((SELECT rr48.canonical_preimage::jsonb#>''{config,c1266_staff_campaign}'' FROM mission_factory_owner.editor_release_readiness rr48 WHERE rr48.singleton)=''{"maxGen":17,"maxUSD":"0.4216","maxHTTP":34,"grant_id":"b925043a-c1b3-434b-8fb4-f335903b2af0","maxCount":17,"residual":{"gen":17,"usd":"0.4395760","http":34,"count":17},"max_pairs":17,"expires_at":"2026-10-20T15:12:18.393948+00:00","not_before":"2026-10-20T14:12:18.393948+00:00","campaign_id":"b2fc5e28-072b-41f2-8dd8-cb5a35a13092","location_id":"0b85f354-9cdb-47e1-baf9-3d266bb7e06b","work_seconds":360,"schema_version":"c1266-staff-campaign/2","cleanup_seconds":360,"history_baseline":{"gen":33,"usd":"0.5524240","http":69,"count":36},"history_scope_ids":["0b1fa6b5-d9c4-4ea3-9ec8-76b1b21e0a0a","21fb8bf3-1df9-4bbf-b2d6-cf7b003b8f30","a853d33f-eecf-484b-b85c-5dc12c25d080","d25d886e-e4f8-4cfe-b8f2-729e96f355d7","c21baa1a-cdac-4401-9131-493eef208a21","780bc131-229e-4142-b1f9-4c6a39b6d070","ef12969b-0958-473c-9016-53052af9d579","2067ace7-c975-4e6c-a621-f82ac23ed18d","6c8d9647-b0de-4c2c-a7e0-6c4a6239ee86","41ec7f9e-9c2c-4476-be14-3ba57a573bc5","8b814fa7-fcdb-4035-9ddb-5bea247aeb36"],"time_policy":{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}}''::jsonb AND c26_proof->''policy''=''{"grant_id":"b925043a-c1b3-434b-8fb4-f335903b2af0","expires_at":"2026-10-20T15:12:18.393948+00:00","not_before":"2026-10-20T14:12:18.393948+00:00","location_id":"0b85f354-9cdb-47e1-baf9-3d266bb7e06b","source_sha256":"eca0639f48346ed0c1fac786c136f557920b61310c38d85f22a5e6a7837231bd","schema_version":"c1266-clean-staff-admission-policy/2","source_mission_id":"5878822d-dc03-4ac2-ad0b-1547f0ab3fc0","source_plan_version_id":"24b1e44a-5597-4fb0-95bd-fb13647764b2","c7_budget_qualification":{"model":"gpt-6-luna","store":false,"http_limit":28,"schema_version":"c1266-clean-staff-budget-qualification/1","generation_limit":14,"reasoning_effort":"high","input_usd_million":0.1,"input_tokens_limit":24000,"output_usd_million":0.5,"output_tokens_limit":20000,"count_upper_cost_usd":"0.0124","scene_cost_budget_usd":"0.3136","generation_upper_cost_usd":"0.0124","count_qualification_sha256":"d8da6486b29f5e6b57272eb9d21660518cdcb57f12ed69209e12f32c37e2d5c0","count_reserve_contract_sha256":"13421de48d6dddbb8c6628fd6a294b90746b3d2b79e56bf617456a5d3cc8e090"},"c7_budget_qualification_sha256":"39af421ce9035831c695f0c8d8bc8157cdfd09918b8b81072433e9031b248959","campaign_id":"b2fc5e28-072b-41f2-8dd8-cb5a35a13092","time_policy":{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}}''::jsonb) AND mission_factory_owner.keys_exact_v2((c26_proof->''admission_attestation''),ARRAY[''schema_version'',''grant_id'',''policy_sha256'',''release_sha256'',''source_mission_id'',''source_plan_version_id'',''source_sha256'',''carrier_mission_id'',''master_session_id'',''start_request_key'',''request_fingerprint'',''activation_id'',''start_receipt_id'',''capability_id'',''board_snapshot_sha256'',''binding_sha256'',''roster_character_ids'',''actor_user_ids'',''c7_budget_qualification_sha256'',''c8_count_qualification_sha256'',''input_tokens_limit'',''output_tokens_limit'',''count_upper_cost_usd'',''generation_upper_cost_usd'',''generation_limit'',''http_limit'',''scene_cost_budget_usd'',''not_before'',''expires_at'',''campaign_id'',''time_policy'']) AND (c26_proof->''admission_attestation'')->>''schema_version''=''c1266-clean-staff-admission-attestation/2'' AND (c26_proof->''admission_attestation'')->>''campaign_id''=''b2fc5e28-072b-41f2-8dd8-cb5a35a13092'' AND (c26_proof->''admission_attestation'')->>''grant_id''=''b925043a-c1b3-434b-8fb4-f335903b2af0'' AND (c26_proof->''admission_attestation'')->>''not_before''=''2026-10-20T14:12:18.393948+00:00'' AND (c26_proof->''admission_attestation'')->>''expires_at''=''2026-10-20T15:12:18.393948+00:00'' AND (c26_proof->''admission_attestation'')->>''source_mission_id''=''5878822d-dc03-4ac2-ad0b-1547f0ab3fc0'' AND (c26_proof->''admission_attestation'')->>''source_plan_version_id''=''24b1e44a-5597-4fb0-95bd-fb13647764b2'' AND (c26_proof->''admission_attestation'')->>''source_sha256''=''eca0639f48346ed0c1fac786c136f557920b61310c38d85f22a5e6a7837231bd'' AND (c26_proof->''admission_attestation'')->''time_policy''=''{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}''::jsonb AND c26_proof->>''finite_admission_sha256''=public.combat_v2_sha256((c26_proof->''admission_attestation'')) AND (c26_proof->''admission_attestation'')->>''policy_sha256''=public.combat_v2_sha256(c26_proof->''policy'') AND (c26_proof->''admission_attestation'')->>''master_session_id''=w.master_session_id::text AND (c26_proof->''admission_attestation'')->>''binding_sha256''=w.definition_sha256 AND (c26_proof->''admission_attestation'')->>''binding_sha256''=c26_proof->>''binding_sha256'' AND (c26_proof->''admission_attestation'')->>''release_sha256''=c26_proof->>''release_sha256'' AND c26_proof->>''release_sha256''=(SELECT rr48.revision_sha256 FROM mission_factory_owner.editor_release_readiness rr48 WHERE rr48.singleton) AND (c26_proof->''admission_attestation'')->>''c7_budget_qualification_sha256''=c26_proof->>''c7_budget_qualification_sha256'' AND c26_proof->>''c7_budget_qualification_sha256''=(c26_proof#>>''{policy,c7_budget_qualification_sha256}'') AND (c26_proof->''admission_attestation'')->>''c8_count_qualification_sha256''=c26_proof->>''c8_count_qualification_sha256'' AND (c26_proof->''admission_attestation'')->''actor_user_ids''=''["b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b","f0856d53-83a6-4de0-bc0c-12c87916e665"]''::jsonb) IS TRUE);
 IF mission_generic_owner.c1266_staff_source_scope_v1(w.master_session_id) IS NOT NULL THEN named_clean48:=coalesce(c26_proof->''policy''=mission_generic_owner.c1266_staff_clean_policy_v1(w.master_session_id,(SELECT rr49.canonical_preimage::jsonb#>''{config,c1266_clean_staff}'' FROM mission_factory_owner.editor_release_readiness rr49 WHERE rr49.singleton)) AND c26_proof#>>''{admission_attestation,schema_version}''=''c1266-clean-staff-admission-attestation/2'',false);END IF;
 IF c26_proof#>>''{admission_attestation,schema_version}''=''c1266-clean-staff-admission-attestation/2'' AND named_clean48 IS DISTINCT FROM TRUE THEN RAISE EXCEPTION ''C1266_NAMED48_CLEAN_ATTESTATION_CLOSED'' USING ERRCODE=''42501'';END IF;
 IF EXISTS(SELECT 1 FROM mission_generic_owner.dispatch_admissions ad
 JOIN mission_factory_owner.editor_release_readiness rr ON rr.singleton
 WHERE ad.master_session_id=w.master_session_id
 AND ad.c7_budget_qualification_sha256=rr.canonical_preimage::jsonb#>>''{config,c1266_clean_staff,c7_budget_qualification_sha256}'')
 AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=w.master_session_id) AND c26_proof IS NULL THEN RAISE EXCEPTION ''C1266_CLEAN_RUNTIME_CLOSED'' USING ERRCODE=''42501'';END IF;
 IF EXISTS(SELECT 1 FROM public.master_v2_sessions s726 WHERE s726.id=w.master_session_id AND s726.owner_kind=''ai_service'' AND s726.location_id=''0b85f354-9cdb-47e1-baf9-3d266bb7e06b''::uuid AND (EXISTS(SELECT 1 FROM mission_generic_owner.flow_staff_sessions f726 WHERE f726.master_session_id=s726.id AND f726.enabled) OR EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources q726 WHERE q726.session_id=s726.id AND q726.availability_scope=''staff'' AND q726.execution_context=''staff_simulation''))) AND NOT mission_academy_owner.staff_carrier_runtime(w.master_session_id) AND NOT mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) THEN RAISE EXCEPTION ''C726_FACTORY_STAFF_SCOPE_CLOSED'' USING ERRCODE=''42501'';END IF;

 if w.state=''failed'' and w.kind=''choice'' and public.combat_v2_is_service()
   and mission_academy_owner.staff_carrier_runtime(w.master_session_id) then
   env:=mission_generic_owner.staff_cached_choice_recover(w.id);
   if env->>''state''=''completed'' then
     return jsonb_build_object(''state'',''completed'',''granted_now'',false);
   end if;
 end if;
 if w.state=''claimed'' and w.lease_expires_at<=clock_timestamp() then
  select * into d from mission_narrative_internal.dispatch_receipts where id=w.dispatch_receipt_id for update;
  if found and w.authorization_id is null and w.dispatch_id is null
   and d.status=''claimed'' and d.dispatch_count=0 and d.charged_cost_usd=0
   and d.upper_bound_cost_usd is null and d.master_session_id=w.master_session_id
   and d.authority_receipt_id=w.id and d.event_kind=''mission_generic_event''
   and d.renderer_version=''mission-generic-runtime/1'' and d.request_key=w.request_key
   and not exists(select 1 from mission_narrative_internal.dispatch_attempts where receipt_id=d.id)
   and not exists(select 1 from mission_narrative_internal.provider_authorizations where receipt_id=d.id)
   and not exists(select 1 from mission_narrative_internal.dispatch_audit where receipt_id=d.id and event_code=''c8_count_started'')
  then
   update mission_narrative_internal.dispatch_receipts set updated_at=clock_timestamp() where id=d.id;
   insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
   values(d.id,''generic_pre_provider_claim_reissued'',jsonb_build_object(''work_id'',w.id,
    ''provider_calls'',0,''charged_cost_usd'',0,''expired_lease_id'',w.lease_id));
   update mission_generic_owner.work_items set state=''ready'',
    lease_id=null,lease_expires_at=null where id=w.id returning * into w;
   dr:=d.id;
  end if;
 end if;
 if w.state<>''ready'' then return jsonb_build_object(''state'',w.state,''granted_now'',false);end if;
 c7_budget:=mission_generic_owner.c7_run_budget_v1(w.master_session_id,true,null);
 if c7_budget->>''allowed''=''false'' then
  IF campaign_scope THEN INSERT INTO public.mission_run_audit(master_session_id,event_code,metadata) VALUES(w.master_session_id,''C1266_CAMPAIGN_PROVIDER_STOP'',jsonb_build_object(''work_id'',w.id,''reason_code'',c7_budget->>''reason_code'',''stop_causes'',c7_budget->''stop_causes'',''boundary'',''claim''));END IF;
  perform mission_generic_owner.c7_run_budget_stop_v1(w.master_session_id);
  return jsonb_build_object(''state'',''ready'',''granted_now'',false,''reason_code'',''MGPG_C7_RUN_BUDGET_STOP'',''provider_calls_remaining'',0);
 end if;
 perform mission_generic_owner.work_assert(w);
 perform mission_generic_owner.assert_runtime(w.master_session_id);
 select * into strict a from mission_generic_owner.dispatch_admissions where master_session_id=w.master_session_id for share;
 select * into strict pol from mission_narrative_internal.runtime_policy where singleton for share;
 perform mission_generic_owner.provider_ready(w.id);
 -- Byte transport limits remain independent from Native token policy.
 pol.max_input_tokens:=(mission_generic_owner.capacity()->>''input_capacity_bytes'')::integer;
 if not a.enabled or (not mission_academy_owner.staff_carrier_runtime(w.master_session_id) and mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NULL and a.calls_authorized>=a.call_limit) or (not pol.enabled and w.master_session_id<>''93d78313-abde-4087-9eb7-7b96bc0fa089''::uuid and not mission_academy_owner.staff_carrier_runtime(w.master_session_id) and not mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id)) or pol.model<>''gpt-6-luna'' or pol.reasoning_effort<>''high'' or pol.store
 then raise exception ''MGD_PROVIDER_CLOSED'';end if;
 if mission_academy_owner.staff_carrier_runtime(w.master_session_id) then
  select count(*) into staff_calls
  from mission_narrative_internal.dispatch_receipts receipt
  join public.master_v2_sessions s on s.id=receipt.master_session_id
  where receipt.event_kind=''mission_generic_event'' and receipt.renderer_version=''mission-generic-runtime/1''
    and receipt.created_at>=clock_timestamp()-interval ''30 days''
    and s.location_id=''0b85f354-9cdb-47e1-baf9-3d266bb7e06b''::uuid and s.owner_kind=''ai_service''
    and exists(select 1 from mission_narrative_internal.dispatch_attempts t where t.receipt_id=receipt.id);
  if staff_calls>=1000 then raise exception ''MGPG_STAFF_ROLLING_BUDGET_EXHAUSTED'';end if;
 end if;
 limits:=jsonb_build_object(''provider_calls_remaining'',case when mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NOT NULL AND c7_budget->>''allowed''=''true'' THEN 1 /* one legal generation HTTP for this work; not a scene ceiling/sentinel */ when c7_budget->>''enforced''=''true'' then least((c7_budget->>''remaining_calls'')::integer/2,a.call_limit-a.calls_authorized) when staff_calls is null then a.call_limit-a.calls_authorized else 1000-staff_calls end,''max_output_tokens'',least(20000,pol.max_output_tokens),
  ''max_input_bytes'',case when w.kind=''director'' and (mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id)) then 65536 else least(49152,pol.max_input_tokens) end,''max_request_bytes'',case when w.kind=''narration'' and (mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id)) then 131072 when w.kind=''director'' and (mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id)) then 65536 else least(65536,pol.max_input_tokens) end,
  ''transport_max_chars'',5000,''provider_timeout_ms'',CASE WHEN c26_proof IS NOT NULL OR c5_proof IS NOT NULL THEN 240000 ELSE 120000 END);
 IF c26_proof IS NOT NULL THEN limits:=limits||jsonb_build_object(''max_input_bytes'',case when w.kind=''director'' then 65536 else 49152 end,''max_request_bytes'',case when w.kind=''narration'' then 131072 else 65536 end);END IF;
 IF c5_proof IS NOT NULL THEN limits:=jsonb_set(limits,''{max_input_bytes}'',to_jsonb((limits->>''max_input_bytes'')::integer*10));END IF;
 if octet_length(w.payload::text)>(limits->>''max_input_bytes'')::integer then raise exception ''MGD_CONTEXT_OVERFLOW'';end if;
 narrative_contract:=mission_public_owner.work_contract_issue_v1(w.id);
  IF w.kind=''director'' AND c5_proof->>''runtime_authorized''=''true'' AND c5_proof->>''execution_context''=''staff_mission'' AND c5_proof#>>''{admission,kind}''=''staff_finite'' AND c5_proof#>>''{admission,resource_scope}''=''staff_simulation'' AND mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NOT NULL AND narrative_contract->>''editorial_profile''=''cinematic_master_1'' THEN limits:=limits||jsonb_build_object(''max_request_bytes'',98304);END IF;
 -- Request transport only: preserve raw-context capacity, tokens and accounting.
 limits:=jsonb_set(limits,''{max_request_bytes}'',to_jsonb((limits->>''max_request_bytes'')::integer*10));
 env:=jsonb_build_object(''work_id'',w.id,''master_session_id'',w.master_session_id,''event_id'',w.event_id,''authority_receipt_id'',w.authority_receipt_id,
  ''payload_sha256'',w.payload_sha256,''definition_sha256'',w.definition_sha256,''revision'',w.revision);
 if narrative_contract is not null then env:=env||jsonb_build_object(''narrative_admission'',narrative_contract);end if;
 fp:=mission_internal.fingerprint(p_request);
 if dr is null then
 insert into mission_narrative_internal.dispatch_receipts(master_session_id,authority_receipt_id,event_kind,renderer_version,request_key,
  request_fingerprint,authority_sha256,envelope,envelope_sha256,status)
 values(w.master_session_id,w.id,''mission_generic_event'',''mission-generic-runtime/1'',w.request_key,fp,
  public.combat_v2_sha256(env),env,public.combat_v2_sha256(env),''claimed'') returning id into dr;
 -- Audit is immutable; preserve the exact Native envelope and all existing authority hashes.
 -- This proves an owned claim under the async contract, not waitUntil registration/completion.
 -- Only newly inserted receipts get this marker. No legacy backfill or marker on lease reissue.
 IF (c26_proof IS NOT NULL OR c5_proof IS NOT NULL) AND limits->''provider_timeout_ms''=''240000''::jsonb THEN
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
  VALUES(dr,''c1266_async_owner_v1'',jsonb_build_object(''schema_version'',''mission-generic-async-owner/1'',
   ''actor_user_id'',p_user,''work_id'',w.id,''request_sha256'',public.combat_v2_sha256(p_request),
   ''envelope_sha256'',public.combat_v2_sha256(env),''provider_timeout_ms'',240000));
 END IF;
 end if;
 -- A complete worker window must fit inside the immutable finite Staff admission.
 IF c26_proof IS NOT NULL AND NOT named_clean48 AND
 (c26_proof#>>''{admission_attestation,expires_at}'')::timestamptz<=clock_timestamp()+interval ''360 seconds''
 THEN RAISE EXCEPTION ''C1266_BACKGROUND_DEADLINE_CLOSED'' USING ERRCODE=''55000'';END IF;
 IF c5_proof IS NOT NULL AND c5_proof#>>''{admission,kind}''=''staff_finite'' AND NOT ((mission_factory_owner.keys_exact_v2(c5_proof->''admission'',ARRAY[''schema_version'',''kind'',''resource_scope'',''finite_admission_sha256'',''grant_id'',''not_before'',''expires_at'',''location_id'',''campaign_id'',''time_policy'']) AND c5_proof->''admission''->>''schema_version''=''c1266-staff-admission-authority/2'' AND c5_proof->''admission''->>''kind''=''staff_finite'' AND c5_proof->''admission''->>''resource_scope''=''staff_simulation'' AND c5_proof->''admission''->>''campaign_id''=''b2fc5e28-072b-41f2-8dd8-cb5a35a13092'' AND c5_proof->''admission''->>''grant_id''=''b925043a-c1b3-434b-8fb4-f335903b2af0'' AND c5_proof->''admission''->>''not_before''=''2026-10-20T14:12:18.393948+00:00'' AND c5_proof->''admission''->>''expires_at''=''2026-10-20T15:12:18.393948+00:00'' AND c5_proof->''admission''->>''location_id''=''0b85f354-9cdb-47e1-baf9-3d266bb7e06b'' AND c5_proof->''admission''->''time_policy''=''{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}''::jsonb AND (c5_proof->''admission''->>''finite_admission_sha256'' ~ ''^[a-f0-9]{64}$'') IS TRUE) IS TRUE) AND
 (c5_proof#>>''{admission,expires_at}'')::timestamptz<=clock_timestamp()+interval ''360 seconds''
 THEN RAISE EXCEPTION ''C1266_BACKGROUND_DEADLINE_CLOSED'' USING ERRCODE=''55000'';END IF;
 update mission_generic_owner.work_items set state=''claimed'',dispatch_receipt_id=dr,lease_id=gen_random_uuid(),
  lease_expires_at=CASE WHEN c5_proof#>>''{admission,schema_version}''=''c1266-staff-admission-authority/3'' THEN clock_timestamp()+interval ''360 seconds'' WHEN c26_proof IS NOT NULL THEN CASE WHEN named_clean48 THEN clock_timestamp()+interval ''360 seconds'' ELSE least(clock_timestamp()+interval ''360 seconds'',(c26_proof#>>''{admission_attestation,expires_at}'')::timestamptz) END WHEN c5_proof IS NOT NULL THEN CASE WHEN ((mission_factory_owner.keys_exact_v2(c5_proof->''admission'',ARRAY[''schema_version'',''kind'',''resource_scope'',''finite_admission_sha256'',''grant_id'',''not_before'',''expires_at'',''location_id'',''campaign_id'',''time_policy'']) AND c5_proof->''admission''->>''schema_version''=''c1266-staff-admission-authority/2'' AND c5_proof->''admission''->>''kind''=''staff_finite'' AND c5_proof->''admission''->>''resource_scope''=''staff_simulation'' AND c5_proof->''admission''->>''campaign_id''=''b2fc5e28-072b-41f2-8dd8-cb5a35a13092'' AND c5_proof->''admission''->>''grant_id''=''b925043a-c1b3-434b-8fb4-f335903b2af0'' AND c5_proof->''admission''->>''not_before''=''2026-10-20T14:12:18.393948+00:00'' AND c5_proof->''admission''->>''expires_at''=''2026-10-20T15:12:18.393948+00:00'' AND c5_proof->''admission''->>''location_id''=''0b85f354-9cdb-47e1-baf9-3d266bb7e06b'' AND c5_proof->''admission''->''time_policy''=''{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}''::jsonb AND (c5_proof->''admission''->>''finite_admission_sha256'' ~ ''^[a-f0-9]{64}$'') IS TRUE) IS TRUE) THEN clock_timestamp()+interval ''360 seconds'' ELSE CASE WHEN c5_proof#>>''{admission,kind}''=''staff_finite'' THEN least(clock_timestamp()+interval ''360 seconds'',(c5_proof#>>''{admission,expires_at}'')::timestamptz) ELSE clock_timestamp()+interval ''360 seconds'' END END ELSE clock_timestamp()+interval ''180 seconds'' END where id=w.id returning * into w;
 IF c7_budget->>''campaign_time_mode''=''budget_or_explicit_stop'' THEN
   IF NOT ((mission_factory_owner.keys_exact_v2(c5_proof->''admission'',ARRAY[''schema_version'',''kind'',''resource_scope'',''finite_admission_sha256'',''grant_id'',''not_before'',''expires_at'',''location_id'',''campaign_id'',''time_policy'']) AND c5_proof->''admission''->>''schema_version''=''c1266-staff-admission-authority/2'' AND c5_proof->''admission''->>''kind''=''staff_finite'' AND c5_proof->''admission''->>''resource_scope''=''staff_simulation'' AND c5_proof->''admission''->>''campaign_id''=''b2fc5e28-072b-41f2-8dd8-cb5a35a13092'' AND c5_proof->''admission''->>''grant_id''=''b925043a-c1b3-434b-8fb4-f335903b2af0'' AND c5_proof->''admission''->>''not_before''=''2026-10-20T14:12:18.393948+00:00'' AND c5_proof->''admission''->>''expires_at''=''2026-10-20T15:12:18.393948+00:00'' AND c5_proof->''admission''->>''location_id''=''0b85f354-9cdb-47e1-baf9-3d266bb7e06b'' AND c5_proof->''admission''->''time_policy''=''{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}''::jsonb AND (c5_proof->''admission''->>''finite_admission_sha256'' ~ ''^[a-f0-9]{64}$'') IS TRUE) IS TRUE) OR c7_budget->''campaign_provider_deadline'' IS DISTINCT FROM ''null''::jsonb THEN RAISE EXCEPTION ''C1266_NAMED47_LEASE_POLICY_CLOSED'' USING ERRCODE=''42501'';END IF;
  ELSIF c7_budget ? ''campaign_provider_deadline'' THEN
  UPDATE mission_generic_owner.work_items SET lease_expires_at=least(lease_expires_at,(c7_budget->>''campaign_provider_deadline'')::timestamptz) WHERE id=w.id RETURNING * INTO w;
 END IF;
 return jsonb_build_object(''state'',''claimed'',''granted_now'',true,''work'',jsonb_build_object(''schema_version'',''mission-generic-work/1'',
  ''work_id'',w.id,''master_session_id'',w.master_session_id,''event_id'',w.event_id,''request_key'',w.request_key,''revision'',w.revision,
  ''step_key'',w.step_key,''run_control_version'',w.run_control_version,''definition_sha256'',w.definition_sha256,
  ''encounter_id'',w.encounter_id,''authority_receipt_id'',w.authority_receipt_id,''kind'',w.kind,''lease_id'',w.lease_id,
  ''server_now'',clock_timestamp(),''lease_expires_at'',w.lease_expires_at,''payload_sha256'',w.payload_sha256,''payload'',w.payload,''limits'',limits,
  ''narrative_admission'',narrative_contract,''narrative_admission_sha256'',case when narrative_contract is not null then public.combat_v2_sha256(narrative_contract) end,
   ''provider_input_contract'',case when c5_proof IS NOT NULL THEN mission_generic_owner.c1266_provider_input_v1(w.id,limits) ELSE case when c26_proof IS NOT NULL then jsonb_build_object(
 ''schema_version'',''mission-generic-provider-input/4'',''input_tokens_limit'',24000,''policy_version'',pol.policy_version,''http_calls_per_generation'',2,
 ''scope'',jsonb_build_object(''schema_version'',''c1266-clean-staff-work-scope/1'',''execution_context'',''staff_mission'',
 ''master_session_id'',w.master_session_id,''work_id'',w.id,''event_id'',w.event_id,''request_key'',w.request_key,''revision'',w.revision,
 ''authority_receipt_id'',w.authority_receipt_id,''definition_sha256'',w.definition_sha256,''payload_sha256'',w.payload_sha256,
 ''payload_schema_version'',w.payload->>''schema_version'',''run_control_version'',w.run_control_version,
 ''narrative_admission_sha256'',case when narrative_contract is not null then public.combat_v2_sha256(narrative_contract) end,
 ''release_sha256'',c26_proof->>''release_sha256'',''finite_admission_sha256'',c26_proof->>''finite_admission_sha256'',
 ''policy_snapshot_sha256'',public.combat_v2_sha256(mission_generic_owner.c8_policy_snapshot_v1(w.id)),
 ''financial_qualification_sha256'',a.c8_count_qualification_sha256),
 ''pricing'',jsonb_build_object(''model'',pol.model,''reasoning_effort'',pol.reasoning_effort,''store'',pol.store,
 ''max_output_tokens'',limits->''max_output_tokens'',''input_usd_million'',pol.input_usd_million,''output_usd_million'',pol.output_usd_million,
 ''count_upper_cost_usd'',''0.0124'',''generation_upper_cost_usd'',''0.0124''),
 ''byte_bounds'',jsonb_build_object(''max_input_bytes'',limits->''max_input_bytes'',''max_request_bytes'',limits->''max_request_bytes'')) else case when a.c7_budget_enforced then case when mission_generic_owner.c8_context24_scope_v1(w.id) then jsonb_build_object(''schema_version'',''mission-generic-provider-input/3'',''input_tokens_limit'',24000,''policy_version'',pol.policy_version,''http_calls_per_generation'',2,''scope'',jsonb_build_object(''schema_version'',''c889-context24-work-scope/1'',''session_id'',w.master_session_id,''work_id'',w.id,''batch_id'',w.authority_receipt_id,''old_work_id'',''c88958e7-8983-4332-a14e-095076f967f4'',''financial_qualification_sha256'',a.c8_count_qualification_sha256,''count_reserve_usd'',''0.0124'',''generation_reserve_usd'',''0.0124''),''pricing'',jsonb_build_object(''model'',pol.model,''reasoning_effort'',pol.reasoning_effort,''store'',pol.store,''max_output_tokens'',20000,''input_usd_million'',pol.input_usd_million,''output_usd_million'',pol.output_usd_million,''count_upper_cost_usd'',''0.0124'',''generation_upper_cost_usd'',''0.0124''),''byte_bounds'',jsonb_build_object(''max_input_bytes'',limits->''max_input_bytes'',''max_request_bytes'',limits->''max_request_bytes'')) else jsonb_build_object(''schema_version'',''mission-generic-provider-input/1'',''input_tokens_limit'',(select max_input_tokens from mission_narrative_internal.runtime_policy where singleton),''policy_version'',pol.policy_version,''http_calls_per_generation'',2)  end else null end end end,
  ''narrative_profile'',case when narrative_contract is not null then narrative_contract->>''editorial_profile'' when w.kind in(''narration'',''director'') and (mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id))
    then ''cinematic_master_1'' else ''legacy'' end) - case when not a.c7_budget_enforced then ''provider_input_contract'' else ''__no_key__'' end);
end $function$
';
 EXECUTE 'CREATE OR REPLACE FUNCTION mission_generic_owner.unified_director_commit(p_work uuid, p_decision jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare ww mission_generic_owner.work_items;uw mission_generic_owner.unified_source_windows;ub mission_generic_owner.unified_batches;
 opportunity jsonb;spec jsonb;sc jsonb;nk text[];mm public.master_v2_sessions;mr public.mission_run_state;result jsonb;eid uuid;role_ref uuid;role_actor uuid;role_sha text;transition_kind text;is_v2 boolean;intent_keys text[];expected_schema text;c1266_bundle jsonb;
begin

 if not mission_generic_owner.flow_scope_enabled((select master_session_id from mission_generic_owner.work_items where id=p_work)) then return mission_generic_owner.flow_previous_unified_director_commit(p_work,p_decision);end if; 
perform mission_ai_board_owner.service_only();
perform 1 from mission_generic_owner.role_window_cursors c
  where c.master_session_id=(select master_session_id from mission_generic_owner.work_items where id=p_work)
  for update;
if not found then raise exception ''MRS_V4_DIRECTOR_CURSOR_REQUIRED'';end if;
perform public.master_v2_lock_scope((select master_session_id from mission_generic_owner.work_items where id=p_work));
select * into strict ww from mission_generic_owner.work_items where id=p_work for update;

 perform mission_generic_owner.work_assert(ww);
 IF mission_generic_owner.c1266_opening_named_v1(ww.master_session_id) AND mission_generic_owner.c1266_execution_authority_v1(ww.master_session_id,false,true) IS NULL THEN RAISE EXCEPTION ''C1266_DIRECTOR5_COMMIT_CLOSED'' USING ERRCODE=''42501'';END IF;
 if ww.kind<>''director'' or (ww.state<>''provider_started'' AND NOT ((ww.id=''e366b9fa-54dc-4abd-8ba6-9ceee83be9a4''::uuid AND ww.master_session_id=''44078c5f-7001-4129-9506-e2f34e68c8ac''::uuid
 AND ww.kind=''director'' AND ww.state=''failed'' AND ww.receipt_id=''07366817-3bf6-4bad-8387-0a4c0d1804f7''::uuid
 AND ww.dispatch_receipt_id=''e9524086-1e03-42d8-866b-1c12eb77840a''::uuid
 AND ww.payload_sha256=''52ae7392cc038543f01c3a9d07532a292c6f9b7cf044d52b2ce2d0a9a7b77754''
 AND ww.result_sha256=''d0a4266f89198307e8c9020af67b4d2b099edc1cbf20e0aea5b38d1b78fc8ea9''
 AND public.combat_v2_sha256(ww.result)=''674c8253e511750022b6d9b477383aed5743ffb2c9ceee7b35a0125c10ac6201''
 AND ww.result->>''ok''=''true'' AND ww.result->>''provider_calls''=''1'' AND ww.result->>''outcome_uncertain''=''false''
 AND EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 wc WHERE wc.work_id=ww.id AND wc.master_session_id=ww.master_session_id
  AND wc.contract_sha256=''0c4e3f0016df29ed7b740336e90ba58d6b1e8d72ac21ed144b9796d32073ecce''
  AND wc.contract_sha256=public.combat_v2_sha256(wc.contract) AND wc.release_sha256=''e58e2e460469dced1c6efb98858b23f043fe8976988ae15bcb25525becc70cd8'')
 AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts dr JOIN mission_narrative_internal.dispatch_audit ga ON ga.receipt_id=dr.id AND ga.event_code=''generic_finalized''
  JOIN staff_ai_quota_private.calls q ON q.source_id=dr.id AND q.producer=''mission_generic_ai'' AND q.call_no=1 AND q.scope_id=ww.master_session_id AND q.state=''settled'' AND q.charged_usd=dr.charged_cost_usd
  WHERE dr.id=ww.dispatch_receipt_id AND dr.status=''success'' AND dr.dispatch_count=1 AND dr.finalized_at IS NOT NULL
   AND dr.master_session_id=ww.master_session_id AND dr.authority_receipt_id=ww.id AND dr.request_key=ww.request_key
   AND ga.details->>''work_id''=ww.id::text AND ga.details->>''receipt_id''=ww.receipt_id::text
   AND ga.details->>''application_error_sqlstate''=''54000'' AND ga.details->''command_receipt''=''null''::jsonb
   AND ga.details->>''stale''=''false'' AND ga.details->>''outcome_uncertain''=''false''
   AND ga.details->>''result_sha256''=ww.result_sha256 AND ga.details->>''result_jsonb_sha256''=public.combat_v2_sha256(ww.result))
 AND EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness rr WHERE rr.singleton AND rr.state=''enabled''
  AND rr.revision_sha256=rr.observed_revision_sha256 AND rr.revision_sha256=encode(extensions.digest(convert_to(rr.canonical_preimage,''UTF8''),''sha256''),''hex'')
  AND rr.canonical_preimage::jsonb#>>''{config,c1266_raw_input_recovery,schema_version}''=''c1266-raw-input-recovery/1''
  AND rr.canonical_preimage::jsonb#>>''{config,c1266_raw_input_recovery,failed_work_id}''=ww.id::text
  AND rr.canonical_preimage::jsonb#>>''{config,c1266_raw_input_recovery,result_sha256}''=ww.result_sha256
  AND rr.canonical_preimage::jsonb#>>''{config,c1266_raw_input_recovery,commit_source_md5}''=(SELECT md5(p.prosrc)FROM pg_proc p WHERE p.oid=''mission_generic_owner.unified_director_commit(uuid,jsonb)''::regprocedure)
  AND rr.canonical_preimage::jsonb#>>''{config,c1266_raw_input_recovery,cached_source_md5}''=(SELECT md5(p.prosrc)FROM pg_proc p WHERE p.oid=''public.mission_generic_staff_republish_failed_v1(uuid,uuid,uuid)''::regprocedure))) AND p_decision IS NOT DISTINCT FROM ww.result->''decision'')) then raise exception ''MUF_DIRECTOR_WORK'';end if;
 select * into strict uw from mission_generic_owner.unified_source_windows where id=ww.authority_receipt_id and work_id=ww.id for update;
 if uw.master_session_id<>ww.master_session_id or uw.step_key<>ww.step_key or uw.run_control_version<>ww.run_control_version
 or uw.definition_sha256<>ww.definition_sha256 or uw.source_sha256<>ww.payload_sha256 or uw.context is distinct from ww.payload->''context''
 or uw.opportunities is distinct from ww.payload->''opportunities'' then raise exception ''MUF_WINDOW_BINDING'';end if;
 if exists(select 1 from jsonb_array_elements(uw.context->''sources'') source_role where source_role->>''kind''=''role'' and not exists(
  select 1 from public.messages sm where sm.id=(source_role->>''id'')::uuid and sm.body=source_role->>''body'' and sm.recipient_user is null
  and encode(extensions.digest(convert_to(sm.body,''UTF8''),''sha256''),''hex'')=source_role->>''sha256'')) then raise exception ''MUF_DIRECTOR_ROLE_DRIFT'';end if;
 IF ww.payload->>''schema_version''=''mission-director-work/4'' THEN
  IF NOT mission_generic_owner.c1266_role_scope_v2(ww.master_session_id,true) THEN RAISE EXCEPTION ''C1266_TEMPORAL_COMMIT_SCOPE'' USING ERRCODE=''42501'';END IF;
  c1266_bundle:=mission_generic_owner.c1266_role_decision_v2(ww.id,p_decision);
  p_decision:=c1266_bundle->''original_core_decision'';
 END IF;
 IF ww.payload->>''schema_version''=''mission-director-work/3'' THEN
  c1266_bundle:=mission_generic_owner.c1266_role_decision_v1(ww.id,p_decision);
  p_decision:=c1266_bundle->''original_core_decision'';
 END IF;
 select * into ub from mission_generic_owner.unified_batches where decision_work_id=ww.id;
 if found then
  if ub.decision is distinct from coalesce(c1266_bundle->''stored_decision'',p_decision) then raise exception ''MUF_DECISION_REPLAY'';end if;return jsonb_build_object(''batch_id'',ub.id,''state'',ub.state);
 end if;
 is_v2:=ww.payload->>''schema_version''=''mission-director-work/2'' OR c1266_bundle IS NOT NULL;
 expected_schema:=''mission-director-proposal/1'';
 if is_v2 then expected_schema:=''mission-director-proposal/2'';end if;
 if not mission_generic_owner.keys_valid(p_decision,array[''schema_version'',''source_window_id'',''source_role_ids'',''source_evidence'',''opportunity_id'',''action_kind'',''entry_side'',''world_reaction_intent'',''npc_intents''])
 or p_decision->>''schema_version'' is distinct from expected_schema or p_decision->>''source_window_id'' is distinct from uw.id::text
 or jsonb_typeof(p_decision->''source_role_ids'') is distinct from ''array'' or jsonb_array_length(p_decision->''source_role_ids'')=0
 or jsonb_typeof(p_decision->''source_evidence'') is distinct from ''array''
 or jsonb_array_length(p_decision->''source_evidence'')>8
 or jsonb_array_length(p_decision->''source_evidence'')=0
 or exists(select 1 from jsonb_array_elements(p_decision->''source_evidence'') ev
  where not mission_generic_owner.keys_valid(ev,array[''role_id'',''quote''])
   or ev->>''role_id'' is null or not ((ev->>''role_id'')::uuid=any(uw.role_ids))
   or not (p_decision->''source_role_ids'' ? (ev->>''role_id''))
   or nullif(btrim(ev->>''quote''),'''') is null or length(ev->>''quote'')>300
   or not exists(select 1 from jsonb_array_elements(uw.context->''sources'') ss
    where ss->>''kind''=''role'' and ss->>''id''=ev->>''role_id''
     and position(ev->>''quote'' in ss->>''body'')>0))
 or (exists(select 1 from mission_generic_owner.unified_source_windows prior_window
   join mission_generic_owner.unified_batches prior_batch on prior_batch.source_window_id=prior_window.id
   where prior_window.master_session_id=ww.master_session_id and prior_window.step_key=ww.step_key
    and prior_window.run_control_version=ww.run_control_version
    and prior_batch.composition_kind=''narrative_continuation'' and prior_batch.state=''published'')
  and not exists(select 1 from jsonb_array_elements(p_decision->''source_evidence'') ev
   join public.messages fresh_role on fresh_role.id=(ev->>''role_id'')::uuid
   where (exists(select 1 from mission_generic_owner.role_window_cursors current_cursor
      join mission_generic_owner.role_latest_v1(ww.master_session_id) latest
        on latest.message_id=fresh_role.id and latest.valid
      where current_cursor.master_session_id=ww.master_session_id)
    or (not exists(select 1 from mission_generic_owner.role_window_cursors current_cursor
      where current_cursor.master_session_id=ww.master_session_id)
      and fresh_role.created_at>(select max(prior_fato.created_at)
       from mission_generic_owner.unified_source_windows prior_window
       join mission_generic_owner.unified_batches prior_batch on prior_batch.source_window_id=prior_window.id
       join public.messages prior_fato on prior_fato.id=prior_batch.message_id
       where prior_window.master_session_id=ww.master_session_id and prior_window.step_key=ww.step_key
        and prior_window.run_control_version=ww.run_control_version
        and prior_batch.composition_kind=''narrative_continuation'' and prior_batch.state=''published'')))))
 or jsonb_typeof(p_decision->''action_kind'') is distinct from ''string''
 or jsonb_typeof(p_decision->''npc_intents'') is distinct from ''array'' or jsonb_typeof(p_decision->''world_reaction_intent'') is distinct from ''string''
 or length(p_decision->>''world_reaction_intent'')>2500
 or exists(select 1 from jsonb_array_elements_text(p_decision->''source_role_ids'') rr where not(rr::uuid=any(uw.role_ids)))
 then raise exception ''MUF_DIRECTOR_PROPOSAL_INVALID'';end if;
 sc:=mission_generic_owner.scene(ww.master_session_id,ww.step_key);
 if p_decision->>''opportunity_id'' is not null then
  select op into strict opportunity from jsonb_array_elements(uw.opportunities) op where op->>''opportunity_id''=p_decision->>''opportunity_id'';
  if p_decision->>''action_kind'' is distinct from opportunity->>''action_kind'' then raise exception ''MUF_DIRECTOR_ACTION_KIND'';end if;
  if opportunity#>>''{destination_context,step_key}'' is not null then
   sc:=mission_generic_owner.scene(ww.master_session_id,opportunity#>>''{destination_context,step_key}'');
  end if;
 elsif p_decision->>''action_kind'' is distinct from ''context'' then raise exception ''MUF_DIRECTOR_CONTEXT_KIND'';
 end if;
 if is_v2 then
  select coalesce(array_agg(ni->>''actor_key''),''{}'') into intent_keys from jsonb_array_elements(p_decision->''npc_intents'') ni;
  select coalesce(array_agg(ni->>''actor_key''),''{}'') into nk from jsonb_array_elements(p_decision->''npc_intents'') ni
    where ni->>''entry_kind''=''offense'';
  -- Context is a real scene: visible PNG may act without a transition.
  -- A synthetic non-combat opportunity reuses the existing entry-policy guard.
  if opportunity is null and cardinality(intent_keys)>0 then
    select jsonb_build_object(
      ''allowed_actor_keys'',coalesce(to_jsonb(array_agg(actor->>''actor_key'')),''[]''::jsonb),
      ''destination_entry_candidates'',coalesce(jsonb_agg(jsonb_build_object(
        ''actor_key'',actor->>''actor_key'',''visible_on_enter'',true,
        ''visibility_trigger_key'',null,
        ''entry_capabilities'',coalesce(actor#>''{entry_policy,entry_capabilities}'',
          ''["speak","gesture","utility"]''::jsonb)-''offense'',
        ''offense_allowed'',false)),''[]''::jsonb),
      ''destination_context'',uw.context,''trigger_key'',null,''encounter_key'',null)
    into opportunity
    from jsonb_array_elements(sc->''actors'') actor
    where mission_generic_owner.npc_entry_actor_visible(
      ww.master_session_id,ww.step_key,actor->>''actor_key'',null)
      and exists(select 1 from jsonb_array_elements(uw.context->''actors'') ca
        where ca->>''id''=''png:''||(actor->>''actor_key''));
  end if;
  if cardinality(intent_keys)<>(select count(distinct actor_key) from unnest(intent_keys) actor_key)
    or (opportunity is null and cardinality(intent_keys)>0)
    or exists(select 1 from jsonb_array_elements(p_decision->''npc_intents'') ni
      where not mission_generic_owner.keys_valid(ni,array[''actor_key'',''intent'',''entry_kind'',''speech_intent''])
        or jsonb_typeof(ni->''intent'')<>''string'' or length(ni->>''intent'')>1500
        or ni->>''entry_kind'' not in(''speak'',''gesture'',''utility'',''offense'')
        or jsonb_typeof(ni->''speech_intent'') not in(''null'',''string'')
        or length(coalesce(ni->>''speech_intent'',''''))>700
        or (ni->>''speech_intent'' is not null and ni->>''entry_kind'' not in(''speak'',''offense''))
        or (ni->>''speech_intent'' is not null and ni->>''entry_kind''=''speak''
          and not exists(select 1 from public.master_v2_sessions staff_session
            where staff_session.id=ww.master_session_id
              and staff_session.location_id=''0b85f354-9cdb-47e1-baf9-3d266bb7e06b''::uuid))
        or not (
          exists(select 1 from jsonb_array_elements(coalesce(opportunity->''destination_entry_candidates'',''[]''::jsonb)) candidate
            where candidate->>''actor_key''=ni->>''actor_key''
              and (candidate->>''visible_on_enter''=''true'' or
                (candidate->>''visibility_trigger_key'' is not null and candidate->>''visibility_trigger_key''=opportunity->>''trigger_key'')
                or (opportunity->>''trigger_key'' is null
                  and mission_generic_owner.npc_entry_actor_visible(ww.master_session_id,ww.step_key,
                    candidate->>''actor_key'',null)))
              and candidate->''entry_capabilities'' ? (ni->>''entry_kind'')
              and (ni->>''speech_intent'' is null or candidate->''entry_capabilities'' ? ''speak'')
              and ((ni->>''entry_kind''<>''speak'' and ni->>''speech_intent'' is null)
                or exists(select 1 from jsonb_array_elements(coalesce(opportunity#>''{destination_context,actors}'',uw.context->''actors'',''[]''::jsonb)) context_actor
                  where context_actor->>''id''=''png:''||(ni->>''actor_key'') and context_actor->>''may_speak''=''true''))
              and (ni->>''entry_kind''<>''offense'' or candidate->>''offense_allowed''=''true''))
          or (opportunity->''allowed_actor_keys'' ? (ni->>''actor_key'')
            and exists(select 1 from jsonb_array_elements(sc->''actors'') legacy_actor
              where legacy_actor->>''actor_key''=ni->>''actor_key''
                and not (legacy_actor ? ''entry_policy''))
            and (ni->>''entry_kind''<>''speak'' or exists(select 1 from jsonb_array_elements(coalesce(opportunity#>''{destination_context,actors}'',uw.context->''actors'',''[]''::jsonb)) context_actor
              where context_actor->>''id''=''png:''||(ni->>''actor_key'') and context_actor->>''may_speak''=''true''))
            and (ni->>''speech_intent'' is null or exists(select 1 from jsonb_array_elements(coalesce(opportunity#>''{destination_context,actors}'',uw.context->''actors'',''[]''::jsonb)) context_actor
              where context_actor->>''id''=''png:''||(ni->>''actor_key'') and context_actor->>''may_speak''=''true''))))
        )
  then raise exception ''MNE_DIRECTOR_ENTRY_INVALID'' using errcode=''22023'';end if;
  if cardinality(nk)>0 and (opportunity->>''encounter_key'' is null or p_decision->>''entry_side''<>''png'')
  then raise exception ''MNE_OFFENSE_ENCOUNTER_REQUIRED'' using errcode=''42501'';end if;
  if p_decision->>''entry_side''=''png'' and cardinality(nk)=0
  then raise exception ''MNE_OFFENSE_INITIATOR_REQUIRED'' using errcode=''22023'';end if;
  if p_decision->>''entry_side'' is null and cardinality(nk)=0 and opportunity is not null then
   opportunity:=jsonb_set(opportunity,''{encounter_key}'',''null''::jsonb);
  end if;
 else
  select coalesce(array_agg(ni->>''actor_key''),''{}'') into nk from jsonb_array_elements(p_decision->''npc_intents'') ni;
  if cardinality(nk)<>(select count(distinct ak) from unnest(nk) ak)
    or exists(select 1 from jsonb_array_elements(p_decision->''npc_intents'') ni
      where not mission_generic_owner.keys_valid(ni,array[''actor_key'',''intent''])
        or jsonb_typeof(ni->''intent'') is distinct from ''string'' or length(ni->>''intent'')>1500
        or not exists(select 1 from jsonb_array_elements(sc->''actors'') aa where aa->>''actor_key''=ni->>''actor_key''))
  then raise exception ''MUF_DIRECTOR_ACTORS'';end if;
  if opportunity is not null and exists(select 1 from unnest(nk) offered_actor where not(opportunity->''allowed_actor_keys'' ? offered_actor))
  then raise exception ''MUF_INTENT_NOT_OFFERED'';end if;
 end if;
 if opportunity->>''encounter_key'' is not null then
  if opportunity->>''trigger_key'' is not null then
    if (p_decision->>''entry_side''<>''ambiguous''
      and not (opportunity->''allowed_entry_sides'' ? (p_decision->>''entry_side'')))
      or (sc ? ''arrival_conflict'' and (sc#>>''{arrival_conflict,encounter_key}'' is distinct from opportunity->>''encounter_key''
        or (p_decision->>''entry_side''<>''ambiguous'' and sc#>>''{arrival_conflict,entry_side}'' is distinct from p_decision->>''entry_side'')))
      or (not(sc ? ''arrival_conflict'') and not mission_generic_owner.mandatory_arrival(
        (select plan_version_id from public.mission_run_state where master_session_id=ww.master_session_id),sc)
       and not (is_v2 and exists(select 1 from jsonb_array_elements(opportunity->''destination_entry_candidates'') candidate
         where candidate->>''offense_allowed''=''true'' and candidate->>''visible_on_enter''=''true'')))
    then raise exception ''MFC_ARRIVAL_CONFLICT_NOT_CERTIFIED'' using errcode=''42501'';end if;
  elsif not exists(select 1 from mission_generic_owner.work_items intro
    join public.messages fato on fato.id=intro.message_id and fato.kind=''fato'' and fato.recipient_user is null
    where intro.master_session_id=ww.master_session_id and intro.kind=''narration'' and intro.state=''completed''
      and intro.step_key=ww.step_key and intro.run_control_version=ww.run_control_version
      and exists(select 1 from public.messages role_msg
        where role_msg.id=any(uw.role_ids) and role_msg.created_at>fato.created_at
          and role_msg.id::text=any(select jsonb_array_elements_text(p_decision->''source_role_ids''))))
  then raise exception ''MFC_CONTACT_OR_NEW_ROLE_REQUIRED'' using errcode=''42501'';end if;
  select es into strict spec from jsonb_array_elements(sc->''encounters'') es where es->>''encounter_key''=opportunity->>''encounter_key'';
  if p_decision->>''entry_side'' not in(''pg'',''png'',''ambiguous'') or p_decision->>''entry_side'' is null then raise exception ''MUF_ENTRY_SIDE'';end if;
  if p_decision->>''entry_side''=''png'' and (cardinality(nk)=0
   or (not is_v2 and exists(select 1 from jsonb_array_elements(spec->''actors'') aa
    where aa->>''team''<>spec->>''pg_team'' and not ((aa->>''actor_key'')=any(nk))
     and not exists(select 1 from mission_academy_owner.roster_actor_rules ar
      where ar.mission_id=(select mission_id from public.master_v2_sessions where id=ww.master_session_id)
       and ar.actor_key=aa->>''actor_key'' and ar.active
       and (select count(*) from public.master_v2_participants p where p.session_id=ww.master_session_id
        and p.left_at is null and p.engagement_state=''attivo'')<ar.min_roster)))
   or exists(select 1 from unnest(nk) ak where not exists(
    select 1 from jsonb_array_elements(spec->''actors'') aa where aa->>''actor_key''=ak and aa->>''team''<>spec->>''pg_team'')))
  then raise exception ''MUF_PNG_INITIATIVE_COHORT'';end if;
 elsif p_decision->>''entry_side'' is not null then raise exception ''MUF_ENTRY_WITHOUT_ENCOUNTER'';end if;
 -- All original source/actor/entry-policy checks above ran on the ORIGINAL proposal.
 -- Only after those checks may a well-formed incompatible effect become context.
 IF c1266_bundle IS NOT NULL THEN
  p_decision:=c1266_bundle->''effective_core_decision'';
  IF c1266_bundle#>>''{role_disposition,status}''=''context_fallback'' THEN
   opportunity:=NULL;spec:=NULL;nk:=''{}''::text[];intent_keys:=''{}''::text[];
   sc:=mission_generic_owner.scene(ww.master_session_id,ww.step_key);
  END IF;
 END IF;
 insert into mission_generic_owner.unified_batches(master_session_id,step_key,run_control_version,entry_side,pg_team,selected_actor_keys,state,
 source_window_id,decision_work_id,decision,decision_sha256,composition_kind,encounter_key,context)
 values(ww.master_session_id,ww.step_key,ww.run_control_version,case when p_decision->>''entry_side''=''ambiguous'' then null else p_decision->>''entry_side'' end,
 spec->>''pg_team'',nk,case when p_decision->>''entry_side''=''ambiguous'' then ''needs_review'' else ''preparing'' end,uw.id,ww.id,p_decision,
 public.combat_v2_sha256(p_decision),case when opportunity->>''encounter_key'' is null then ''narrative_continuation'' else ''entry_''||(p_decision->>''entry_side'') end,
 opportunity->>''encounter_key'',uw.context) returning * into ub;

 IF c1266_bundle IS NOT NULL THEN
  UPDATE mission_generic_owner.unified_batches SET decision=c1266_bundle->''stored_decision'',
   decision_sha256=public.combat_v2_sha256(c1266_bundle->''stored_decision'') WHERE id=ub.id RETURNING * INTO ub;
 END IF;
 if ub.state=''needs_review'' then return jsonb_build_object(''batch_id'',ub.id,''state'',''needs_review'');end if;

 if not is_v2 then raise exception ''MRS_V4_DIRECTOR_PROPOSAL_V2_REQUIRED'';end if;
 if coalesce(uw.context->>''source_revision'','''') !~ ''^[0-9a-f]{64}$''
   or uw.context->>''source_revision'' is distinct from mission_generic_owner.role_source_revision_v1(ww.master_session_id)
 then raise exception ''MRS_V4_DIRECTOR_STALE_ROLE'' using errcode=''40001'';end if;
 if opportunity->>''trigger_key'' is not null
   and jsonb_typeof(opportunity->''destination_context'') is distinct from ''object''
 then raise exception ''MRS_V4_DESTINATION_CONTEXT_REQUIRED'' using errcode=''55000'';end if;
 if is_v2 and exists(select 1 from jsonb_array_elements(p_decision->''npc_intents'') ni
   where ni->>''entry_kind''=''offense'' and ni->>''actor_key'' !~ ''^[a-z][a-z0-9_]{0,63}$'')
 then raise exception ''MRS_V4_DIRECTOR_SLOT_KEY'';end if;
 if opportunity->>''quest_terminal_decision_key'' is not null then return mission_factory_owner.quest_terminal_director_v1(ub.id,opportunity->>''quest_terminal_decision_key'');end if;
 update mission_generic_owner.unified_batches b set
   selected_actor_keys=coalesce((select array_agg(ni->>''actor_key'' order by ni->>''actor_key'')
     from jsonb_array_elements(p_decision->''npc_intents'') ni where ni->>''entry_kind''=''offense''),''{}''::text[]),
   context=mission_generic_owner.npc_entry_visible_context(
     jsonb_set(
       jsonb_set(coalesce(opportunity->''destination_context'',uw.context),
         ''{source_revision}'',to_jsonb(uw.context->>''source_revision''),true),
       ''{resolved_facts}'',
       coalesce(coalesce(opportunity->''destination_context'',uw.context)->''resolved_facts'',''{}''::jsonb)
         || case when opportunity->>''encounter_key'' is not null
              and opportunity->>''trigger_key'' is not null
              and coalesce(opportunity#>>''{destination_context,step_key}'',ww.step_key)<>ww.step_key
            then jsonb_build_object(''arrival_conflict'',jsonb_build_object(
              ''encounter_key'',opportunity->>''encounter_key'',
              ''entry_side'',p_decision->>''entry_side'',
              ''public_cause'',opportunity->>''label''))
            else ''{}''::jsonb end,true),
     mission_generic_owner.scene(ww.master_session_id,
       coalesce(opportunity#>>''{destination_context,step_key}'',ww.step_key)),ub.id)
 where b.id=ub.id;
 perform mission_generic_owner.unified_enqueue_writer(ub.id);
 return jsonb_build_object(''batch_id'',ub.id,''state'',''writer_ready'');
end;
$function$
';
 EXECUTE 'CREATE OR REPLACE FUNCTION mission_generic_owner.unified_batch_payload(p_batch uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM mission_generic_owner.unified_batches b38 WHERE b38.id=p_batch AND b38.decision#>>''{role_interpretation,schema_version}''=''mission-role-interpretation/4'') THEN
 declare ub mission_generic_owner.unified_batches;uw mission_generic_owner.unified_source_windows;
 source jsonb:=''[]'';ctx jsonb;srcctx jsonb;part jsonb;parts jsonb:=''[]'';pending jsonb:=''[]'';windows jsonb:=''[]'';receipts jsonb;result jsonb;c1266_roles boolean:=false;peer boolean;
begin
 select * into strict ub from mission_generic_owner.unified_batches where id=p_batch;
 if ub.state not in(''preparing'',''ready'') then raise exception ''MUF_BATCH_STATE'';end if;
 peer:=ub.decision#>>''{role_interpretation,schema_version}''=''mission-role-interpretation/4'';
 IF peer AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items pw WHERE pw.id=ub.decision_work_id AND pw.master_session_id=ub.master_session_id AND pw.payload#>>''{peer_confirmation,schema_version}''=''mission-peer-confirmation-contract/2'') THEN RAISE EXCEPTION ''C1266_PEER_BATCH_PROVENANCE'' USING ERRCODE=''40001'';END IF;
 IF ub.decision->>''schema_version''=''mission-director-proposal/4'' THEN
  IF NOT mission_generic_owner.c1266_role_scope_v2(ub.master_session_id,false) OR ub.decision#>>''{role_interpretation,schema_version}'' IS DISTINCT FROM (CASE WHEN peer THEN ''mission-role-interpretation/4'' ELSE ''mission-role-interpretation/2'' END) OR ub.decision#>>''{role_disposition,schema_version}'' IS DISTINCT FROM (CASE WHEN peer THEN ''mission-role-disposition/4'' ELSE ''mission-role-disposition/2'' END) THEN RAISE EXCEPTION ''C1266_TEMPORAL_BATCH_SCOPE'';END IF;
  c1266_roles:=true;
 ELSE
  c1266_roles:=ub.decision->>''schema_version''=''mission-director-proposal/3'';
 END IF;
 IF c1266_roles AND NOT mission_generic_owner.c1266_role_scope_v1(ub.master_session_id,false) THEN RAISE EXCEPTION ''C1266_ROLE_BATCH_SCOPE'' USING ERRCODE=''42501'';END IF;
 receipts:=jsonb_build_array(ub.id);ctx:=ub.context;
 if ctx is not null then ctx:=jsonb_set(ctx,''{authority_receipt_id}'',to_jsonb(ub.id));end if;
 if ub.source_window_id is not null then
  select * into strict uw from mission_generic_owner.unified_source_windows where id=ub.source_window_id;
  if ctx is not null then
   ctx:=jsonb_set(ctx,''{sources}'',(select coalesce(jsonb_agg(ss),''[]'') from jsonb_array_elements(ctx->''sources'') ss where ss->>''kind''<>''role''));
  end if;
  srcctx:=uw.context;
  windows:=jsonb_build_array(jsonb_build_object(''source_window_id'',uw.id,''through'',uw.through_at,''role_ids'',to_jsonb(uw.role_ids),''source_sha256'',uw.source_sha256));
 end if;
 if ub.source_report_id is not null then
  source:=jsonb_build_array(mission_generic_owner.combat_narrative_source(ub.master_session_id,ub.source_report_id)->''payload'');
  receipts:=receipts||jsonb_build_array(ub.source_report_id);
 end if;
 if ub.secondary_report_id is not null then
  source:=source||jsonb_build_array(mission_generic_owner.combat_narrative_source(ub.master_session_id,ub.secondary_report_id)->''payload'');
  receipts:=receipts||jsonb_build_array(ub.secondary_report_id);
 end if;
 for part in select value from jsonb_array_elements(source) loop
  if jsonb_array_length(coalesce(part->''roleless_declarations'',''[]''))>0 then
   receipts:=receipts||(select jsonb_agg(rd->''receipt_id'') from jsonb_array_elements(part->''roleless_declarations'') rd);
   part:=jsonb_build_object(''schema_version'',''mission-unified-mechanical-report/1'',
    ''native_scene'',part-''roleless_declarations'',''roleless_declarations'',part->''roleless_declarations'');
  end if;
  parts:=parts||jsonb_build_array(part);
 end loop;
 source:=parts;
 if ub.next_round_id is not null and ub.entry_side=''png'' then
  pending:=mission_generic_owner.unified_pending(ub.next_round_id);
  receipts:=receipts||(select coalesce(jsonb_agg(pp->''receipt_id''),''[]'') from jsonb_array_elements(pending) pp)
   ||(select coalesce(jsonb_agg(pp#>''{roleless_receipt,receipt_id}''),''[]'') from jsonb_array_elements(pending) pp where pp ? ''roleless_receipt'');
 end if;
 if ctx is not null and ub.source_window_id is null then
  -- Combat continuation context is deliberately free of a second chat-role window.
  ctx:=jsonb_set(ctx,''{sources}'',(select coalesce(jsonb_agg(ss),''[]'') from jsonb_array_elements(ctx->''sources'') ss where ss->>''kind''<>''role''));
 end if;
 select jsonb_agg(distinct ri) into receipts from jsonb_array_elements(receipts) ri;
 -- C1266 temporal writer: role metadata belongs only to the attested source_context.
 -- Preserve all destination/current narrative sources, facts and continuity fields.
 IF c1266_roles AND ub.decision->>''schema_version''=''mission-director-proposal/4''
   AND ctx IS NOT NULL AND srcctx IS NOT NULL THEN
  ctx:=ctx-''public_destination_sources''-''role_progression_basis'';
 END IF;
 result:=jsonb_build_object(''schema_version'',''mission-generic-narration/3'',''mode'',''unified'',''batch_id'',ub.id,
 ''composition_kind'',ub.composition_kind,''director_proposal'',ub.decision,''resolved_scenes'',source,''mission_context'',ctx,''source_context'',srcctx,''pending_offensives'',pending,
 ''preparation_receipt_id'',ub.id,''publication_barrier'',jsonb_build_object(''closed'',true,''required_receipt_ids'',receipts,''receipt_ids'',receipts),
 ''source_windows'',windows,''next_state_receipt_id'',ub.id);

 if ub.source_window_id is not null
   and mission_generic_owner.flow_scope_enabled(ub.master_session_id)
   and exists(select 1 from mission_generic_owner.role_window_cursors c
     where c.master_session_id=ub.master_session_id) then
   if coalesce(uw.context->>''source_revision'','''') !~ ''^[0-9a-f]{64}$''
     or (ub.decision->>''schema_version''<>''mission-director-proposal/2'' AND NOT c1266_roles)
     or ub.next_round_id is not null or jsonb_array_length(pending)<>0
   then raise exception ''MRS_V4_PAYLOAD_BINDING'' using errcode=''40001'';end if;
   if exists(select 1 from jsonb_array_elements(ub.decision->''npc_intents'') ni
       where ni->>''entry_kind''=''offense''
         and (ni->>''actor_key'' !~ ''^[a-z][a-z0-9_]{0,63}$''))
     or (select count(*) from jsonb_array_elements(ub.decision->''npc_intents'') ni
           where ni->>''entry_kind''=''offense'')
        <> (select count(distinct ni->>''actor_key'') from jsonb_array_elements(ub.decision->''npc_intents'') ni
           where ni->>''entry_kind''=''offense'')
   then raise exception ''MRS_V4_SLOT_KEYS'';end if;
   if ub.composition_kind=''entry_png'' then
     if coalesce(ub.selected_actor_keys,''{}''::text[]) is distinct from
       coalesce((select array_agg(ni->>''actor_key'' order by ni->>''actor_key'')
          from jsonb_array_elements(ub.decision->''npc_intents'') ni
          where ni->>''entry_kind''=''offense''),''{}''::text[])
       or cardinality(ub.selected_actor_keys)=0
     then raise exception ''MRS_V4_ENTRY_COHORT'';end if;
   elsif exists(select 1 from jsonb_array_elements(ub.decision->''npc_intents'') ni
       where ni->>''entry_kind''=''offense'')
   then raise exception ''MRS_V4_OFFENSE_WITHOUT_ENTRY'';end if;
   result:=result||jsonb_build_object(
     ''source_revision'',uw.context->>''source_revision'',
     ''offense_slots'',coalesce((select jsonb_agg(jsonb_build_object(
       ''slot_id'',ni->>''actor_key'',''actor_key'',ni->>''actor_key'') order by ni->>''actor_key'')
       from jsonb_array_elements(ub.decision->''npc_intents'') ni
       where ni->>''entry_kind''=''offense''),''[]''::jsonb),
     ''pending_offensives'',''[]''::jsonb);
   result:=jsonb_set(result,''{schema_version}'',to_jsonb(''mission-generic-narration/4''::text));
 end if;
 IF ub.decision->''current_projection'' IS DISTINCT FROM mission_generic_owner.c1266_role_current_projection_v2(ub.decision_work_id,ub.decision->''role_interpretation'') OR ub.decision#>>''{role_disposition,current_projection_sha256}'' IS DISTINCT FROM public.combat_v2_sha256(ub.decision->''current_projection'') OR ub.decision#>>''{role_disposition,effect}'' IS DISTINCT FROM(CASE WHEN ub.decision->>''opportunity_id'' IS NULL THEN ''context'' ELSE (SELECT op#>>''{effect_policy,scope}'' FROM jsonb_array_elements(uw.opportunities) op WHERE op->>''opportunity_id''=ub.decision->>''opportunity_id'') END) THEN RAISE EXCEPTION ''C1266_PEER4_BATCH_FULL_PROJECTION'' USING ERRCODE=''40001'';END IF;
 IF c1266_roles THEN
  IF (ub.decision->>''schema_version''=''mission-director-proposal/4'' AND (NOT mission_generic_owner.c1266_role_keys_v1(ub.decision->''role_disposition'',ARRAY[''schema_version'',''source_window_id'',''source_revision'',''decision_work_id'',''proposed_opportunity_id'',''effective_opportunity_id'',''status'',''reason'',''interpretation_sha256'',''temporal_contract_sha256'',''current_projection_sha256'',''effect'']) OR ub.decision#>>''{role_disposition,temporal_contract_sha256}'' IS DISTINCT FROM (CASE WHEN peer THEN ''0603ab23e76750b5babeb41421bc84b551b959945f21267ffd7169140732f1e8'' ELSE ''64adc5a2eec27bc4ac02ffa3d9f8afd485f3a1f9ea4879b9ccfe1c3bb5b32cc2'' END) OR ub.decision#>>''{role_disposition,current_projection_sha256}'' IS DISTINCT FROM public.combat_v2_sha256(mission_generic_owner.c1266_role_current_projection_v2(ub.decision_work_id,ub.decision->''role_interpretation'')))) OR (ub.decision->>''schema_version''=''mission-director-proposal/3'' AND NOT mission_generic_owner.c1266_role_keys_v1(ub.decision->''role_disposition'',ARRAY[''schema_version'',''source_window_id'',''source_revision'',''decision_work_id'',''proposed_opportunity_id'',''effective_opportunity_id'',''status'',''reason'',''interpretation_sha256'']))
   OR ub.decision#>>''{role_disposition,decision_work_id}'' IS DISTINCT FROM ub.decision_work_id::text
   OR ub.decision#>>''{role_disposition,interpretation_sha256}'' IS DISTINCT FROM public.combat_v2_sha256(ub.decision->''role_interpretation'')
   OR ub.decision#>''{role_disposition,effective_opportunity_id}'' IS DISTINCT FROM ub.decision->''opportunity_id''
  THEN RAISE EXCEPTION ''C1266_ROLE_DISPOSITION_BINDING'' USING ERRCODE=''40001'';END IF;
  result:=jsonb_set(result,''{director_proposal}'',ub.decision-''role_disposition''-''current_projection'')||jsonb_build_object(
   ''role_interpretation'',ub.decision->''role_interpretation'',''role_disposition'',ub.decision->''role_disposition'',''current_projection'',ub.decision->''current_projection'');
 END IF;
 if octet_length(result::text)>10*(mission_generic_owner.capacity()->>''input_capacity_bytes'')::integer then raise exception ''MUF_CONTEXT_OVERFLOW'' using errcode=''54000'';end if;
 return mission_factory_owner.quest_step_payload_v1(ub.master_session_id,ub.id,result);
end;
 END IF;
 declare ub mission_generic_owner.unified_batches;uw mission_generic_owner.unified_source_windows;
 source jsonb:=''[]'';ctx jsonb;srcctx jsonb;part jsonb;parts jsonb:=''[]'';pending jsonb:=''[]'';windows jsonb:=''[]'';receipts jsonb;result jsonb;c1266_roles boolean:=false;peer boolean;
begin
 select * into strict ub from mission_generic_owner.unified_batches where id=p_batch;
 if ub.state not in(''preparing'',''ready'') then raise exception ''MUF_BATCH_STATE'';end if;
 peer:=ub.decision#>>''{role_interpretation,schema_version}''=''mission-role-interpretation/3'';
 IF peer AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items pw WHERE pw.id=ub.decision_work_id AND pw.master_session_id=ub.master_session_id AND pw.payload#>>''{peer_confirmation,schema_version}''=''mission-peer-confirmation-contract/1'') THEN RAISE EXCEPTION ''C1266_PEER_BATCH_PROVENANCE'' USING ERRCODE=''40001'';END IF;
 IF ub.decision->>''schema_version''=''mission-director-proposal/4'' THEN
  IF NOT mission_generic_owner.c1266_role_scope_v2(ub.master_session_id,false) OR ub.decision#>>''{role_interpretation,schema_version}'' IS DISTINCT FROM (CASE WHEN peer THEN ''mission-role-interpretation/3'' ELSE ''mission-role-interpretation/2'' END) OR ub.decision#>>''{role_disposition,schema_version}'' IS DISTINCT FROM (CASE WHEN peer THEN ''mission-role-disposition/3'' ELSE ''mission-role-disposition/2'' END) THEN RAISE EXCEPTION ''C1266_TEMPORAL_BATCH_SCOPE'';END IF;
  c1266_roles:=true;
 ELSE
  c1266_roles:=ub.decision->>''schema_version''=''mission-director-proposal/3'';
 END IF;
 IF c1266_roles AND NOT mission_generic_owner.c1266_role_scope_v1(ub.master_session_id,false) THEN RAISE EXCEPTION ''C1266_ROLE_BATCH_SCOPE'' USING ERRCODE=''42501'';END IF;
 receipts:=jsonb_build_array(ub.id);ctx:=ub.context;
 if ctx is not null then ctx:=jsonb_set(ctx,''{authority_receipt_id}'',to_jsonb(ub.id));end if;
 if ub.source_window_id is not null then
  select * into strict uw from mission_generic_owner.unified_source_windows where id=ub.source_window_id;
  if ctx is not null then
   ctx:=jsonb_set(ctx,''{sources}'',(select coalesce(jsonb_agg(ss),''[]'') from jsonb_array_elements(ctx->''sources'') ss where ss->>''kind''<>''role''));
  end if;
  srcctx:=uw.context;
  windows:=jsonb_build_array(jsonb_build_object(''source_window_id'',uw.id,''through'',uw.through_at,''role_ids'',to_jsonb(uw.role_ids),''source_sha256'',uw.source_sha256));
 end if;
 if ub.source_report_id is not null then
  source:=jsonb_build_array(mission_generic_owner.combat_narrative_source(ub.master_session_id,ub.source_report_id)->''payload'');
  receipts:=receipts||jsonb_build_array(ub.source_report_id);
 end if;
 if ub.secondary_report_id is not null then
  source:=source||jsonb_build_array(mission_generic_owner.combat_narrative_source(ub.master_session_id,ub.secondary_report_id)->''payload'');
  receipts:=receipts||jsonb_build_array(ub.secondary_report_id);
 end if;
 for part in select value from jsonb_array_elements(source) loop
  if jsonb_array_length(coalesce(part->''roleless_declarations'',''[]''))>0 then
   receipts:=receipts||(select jsonb_agg(rd->''receipt_id'') from jsonb_array_elements(part->''roleless_declarations'') rd);
   part:=jsonb_build_object(''schema_version'',''mission-unified-mechanical-report/1'',
    ''native_scene'',part-''roleless_declarations'',''roleless_declarations'',part->''roleless_declarations'');
  end if;
  parts:=parts||jsonb_build_array(part);
 end loop;
 source:=parts;
 if ub.next_round_id is not null and ub.entry_side=''png'' then
  pending:=mission_generic_owner.unified_pending(ub.next_round_id);
  receipts:=receipts||(select coalesce(jsonb_agg(pp->''receipt_id''),''[]'') from jsonb_array_elements(pending) pp)
   ||(select coalesce(jsonb_agg(pp#>''{roleless_receipt,receipt_id}''),''[]'') from jsonb_array_elements(pending) pp where pp ? ''roleless_receipt'');
 end if;
 if ctx is not null and ub.source_window_id is null then
  -- Combat continuation context is deliberately free of a second chat-role window.
  ctx:=jsonb_set(ctx,''{sources}'',(select coalesce(jsonb_agg(ss),''[]'') from jsonb_array_elements(ctx->''sources'') ss where ss->>''kind''<>''role''));
 end if;
 select jsonb_agg(distinct ri) into receipts from jsonb_array_elements(receipts) ri;
 -- C1266 temporal writer: role metadata belongs only to the attested source_context.
 -- Preserve all destination/current narrative sources, facts and continuity fields.
 IF c1266_roles AND ub.decision->>''schema_version''=''mission-director-proposal/4''
   AND ctx IS NOT NULL AND srcctx IS NOT NULL THEN
  ctx:=ctx-''public_destination_sources''-''role_progression_basis'';
 END IF;
 result:=jsonb_build_object(''schema_version'',''mission-generic-narration/3'',''mode'',''unified'',''batch_id'',ub.id,
 ''composition_kind'',ub.composition_kind,''director_proposal'',ub.decision,''resolved_scenes'',source,''mission_context'',ctx,''source_context'',srcctx,''pending_offensives'',pending,
 ''preparation_receipt_id'',ub.id,''publication_barrier'',jsonb_build_object(''closed'',true,''required_receipt_ids'',receipts,''receipt_ids'',receipts),
 ''source_windows'',windows,''next_state_receipt_id'',ub.id);

 if ub.source_window_id is not null
   and mission_generic_owner.flow_scope_enabled(ub.master_session_id)
   and exists(select 1 from mission_generic_owner.role_window_cursors c
     where c.master_session_id=ub.master_session_id) then
   if coalesce(uw.context->>''source_revision'','''') !~ ''^[0-9a-f]{64}$''
     or (ub.decision->>''schema_version''<>''mission-director-proposal/2'' AND NOT c1266_roles)
     or ub.next_round_id is not null or jsonb_array_length(pending)<>0
   then raise exception ''MRS_V4_PAYLOAD_BINDING'' using errcode=''40001'';end if;
   if exists(select 1 from jsonb_array_elements(ub.decision->''npc_intents'') ni
       where ni->>''entry_kind''=''offense''
         and (ni->>''actor_key'' !~ ''^[a-z][a-z0-9_]{0,63}$''))
     or (select count(*) from jsonb_array_elements(ub.decision->''npc_intents'') ni
           where ni->>''entry_kind''=''offense'')
        <> (select count(distinct ni->>''actor_key'') from jsonb_array_elements(ub.decision->''npc_intents'') ni
           where ni->>''entry_kind''=''offense'')
   then raise exception ''MRS_V4_SLOT_KEYS'';end if;
   if ub.composition_kind=''entry_png'' then
     if coalesce(ub.selected_actor_keys,''{}''::text[]) is distinct from
       coalesce((select array_agg(ni->>''actor_key'' order by ni->>''actor_key'')
          from jsonb_array_elements(ub.decision->''npc_intents'') ni
          where ni->>''entry_kind''=''offense''),''{}''::text[])
       or cardinality(ub.selected_actor_keys)=0
     then raise exception ''MRS_V4_ENTRY_COHORT'';end if;
   elsif exists(select 1 from jsonb_array_elements(ub.decision->''npc_intents'') ni
       where ni->>''entry_kind''=''offense'')
   then raise exception ''MRS_V4_OFFENSE_WITHOUT_ENTRY'';end if;
   result:=result||jsonb_build_object(
     ''source_revision'',uw.context->>''source_revision'',
     ''offense_slots'',coalesce((select jsonb_agg(jsonb_build_object(
       ''slot_id'',ni->>''actor_key'',''actor_key'',ni->>''actor_key'') order by ni->>''actor_key'')
       from jsonb_array_elements(ub.decision->''npc_intents'') ni
       where ni->>''entry_kind''=''offense''),''[]''::jsonb),
     ''pending_offensives'',''[]''::jsonb);
   result:=jsonb_set(result,''{schema_version}'',to_jsonb(''mission-generic-narration/4''::text));
 end if;
 IF c1266_roles THEN
  IF (ub.decision->>''schema_version''=''mission-director-proposal/4'' AND (NOT mission_generic_owner.c1266_role_keys_v1(ub.decision->''role_disposition'',ARRAY[''schema_version'',''source_window_id'',''source_revision'',''decision_work_id'',''proposed_opportunity_id'',''effective_opportunity_id'',''status'',''reason'',''interpretation_sha256'',''temporal_contract_sha256'',''current_projection_sha256'']) OR ub.decision#>>''{role_disposition,temporal_contract_sha256}'' IS DISTINCT FROM (CASE WHEN peer THEN ''3fdeaa942bcf3ba217a976f7b0896f4594721fa45cde9ff8ed7bddf15391feda'' ELSE ''64adc5a2eec27bc4ac02ffa3d9f8afd485f3a1f9ea4879b9ccfe1c3bb5b32cc2'' END) OR ub.decision#>>''{role_disposition,current_projection_sha256}'' IS DISTINCT FROM public.combat_v2_sha256(mission_generic_owner.c1266_role_current_projection_v2(ub.decision_work_id,ub.decision->''role_interpretation'')))) OR (ub.decision->>''schema_version''=''mission-director-proposal/3'' AND NOT mission_generic_owner.c1266_role_keys_v1(ub.decision->''role_disposition'',ARRAY[''schema_version'',''source_window_id'',''source_revision'',''decision_work_id'',''proposed_opportunity_id'',''effective_opportunity_id'',''status'',''reason'',''interpretation_sha256'']))
   OR ub.decision#>>''{role_disposition,decision_work_id}'' IS DISTINCT FROM ub.decision_work_id::text
   OR ub.decision#>>''{role_disposition,interpretation_sha256}'' IS DISTINCT FROM public.combat_v2_sha256(ub.decision->''role_interpretation'')
   OR ub.decision#>''{role_disposition,effective_opportunity_id}'' IS DISTINCT FROM ub.decision->''opportunity_id''
  THEN RAISE EXCEPTION ''C1266_ROLE_DISPOSITION_BINDING'' USING ERRCODE=''40001'';END IF;
  result:=jsonb_set(result,''{director_proposal}'',ub.decision-''role_disposition'')||jsonb_build_object(
   ''role_interpretation'',ub.decision->''role_interpretation'',''role_disposition'',ub.decision->''role_disposition'');
 END IF;
 if octet_length(result::text)>(mission_generic_owner.capacity()->>''input_capacity_bytes'')::integer then raise exception ''MUF_CONTEXT_OVERFLOW'' using errcode=''54000'';end if;
 return mission_factory_owner.quest_step_payload_v1(ub.master_session_id,ub.id,result);
end;
END
$function$
';
 EXECUTE 'CREATE OR REPLACE FUNCTION public.mission_generic_counted_resume_v1(p_user uuid, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
DECLARE w mission_generic_owner.work_items;wc mission_public_owner.work_contracts_v1;
 r mission_narrative_internal.dispatch_receipts;ct staff_ai_quota_private.calls;
 sd jsonb;pf jsonb;marker jsonb;authority jsonb;e jsonb;q jsonb;snap jsonb;budget jsonb;
 old_work jsonb;old_receipt jsonb;old_contract jsonb;old_ticket jsonb;
 old_lease uuid;old_until timestamptz;new_lease uuid;new_until timestamptz;
 h jsonb;hid bigint;n integer;limits jsonb;dto jsonb;reuse jsonb;req uuid;
BEGIN
 PERFORM mission_ai_board_owner.service_only();
 IF p_user IS NULL OR mission_factory_owner.keys_exact_v2(p_request,ARRAY[''schema_version'',''master_session_id'',''event_id'',''request_key'',''expected_revision'']) IS DISTINCT FROM TRUE
 OR p_request->>''schema_version'' IS DISTINCT FROM ''mission-generic-request/1''
 OR jsonb_typeof(p_request->''expected_revision'') IS DISTINCT FROM ''number''
 OR (p_request->>''expected_revision'' ~ ''^[1-9][0-9]{0,15}$'') IS DISTINCT FROM TRUE
 OR (p_request->>''expected_revision'')::numeric>9007199254740991
 THEN RAISE EXCEPTION ''MANUAL_COUNTED_RESUME_ARGUMENTS'' USING ERRCODE=''22023'';END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended(''C1266:GENERIC-AI:AVAILABILITY'',0));
 LOCK TABLE mission_narrative_internal.runtime_policy IN SHARE MODE;
 PERFORM mission_generic_owner.dispatch_user((p_request->>''master_session_id'')::uuid,p_user);
 PERFORM 1 FROM mission_generic_owner.role_window_cursors WHERE master_session_id=(p_request->>''master_session_id'')::uuid FOR UPDATE;
 PERFORM 1 FROM public.master_v2_sessions WHERE id=(p_request->>''master_session_id'')::uuid FOR UPDATE;
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE master_session_id=(p_request->>''master_session_id'')::uuid
 AND event_id=(p_request->>''event_id'')::uuid AND request_key=(p_request->>''request_key'')::uuid
 AND revision=(p_request->>''expected_revision'')::bigint FOR UPDATE;
 PERFORM 1 FROM mission_generic_owner.dispatch_admissions WHERE master_session_id=w.master_session_id FOR UPDATE;
 SELECT * INTO STRICT r FROM mission_narrative_internal.dispatch_receipts WHERE id=w.dispatch_receipt_id FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.master_v2_participants mp ON mp.user_id_snapshot=p.id
 JOIN public.characters ch ON ch.id=mp.character_id AND ch.user_id=p.id
 JOIN public.master_v2_sessions ms ON ms.id=mp.session_id
 JOIN public.locations l ON l.id=ms.location_id AND l.is_active AND l.is_test
 JOIN mission_generic_owner.start_claims sc ON sc.session_id=ms.id AND sc.actor_user_id=p.id AND sc.simulation AND sc.state=''bound''
 WHERE p.id=p_user AND p.role IN(''admin'',''master'') AND mp.session_id=w.master_session_id
 AND mp.engagement_state=''attivo'' AND mp.left_at IS NULL AND ms.closed_at IS NULL AND ms.suspended_at IS NULL)
 THEN RAISE EXCEPTION ''MANUAL_COUNTED_RESUME_OWNER'' USING ERRCODE=''42501'';END IF;
 SELECT count(*),jsonb_agg(details)->0 INTO n,marker FROM mission_narrative_internal.dispatch_audit WHERE receipt_id=r.id AND event_code=''c1266_async_owner_v1'';
 IF n<>1 OR marker->>''schema_version'' IS DISTINCT FROM ''mission-generic-async-owner/1''
 OR marker->>''work_id'' IS DISTINCT FROM w.id::text OR marker->>''actor_user_id'' IS DISTINCT FROM p_user::text
 OR marker->>''request_sha256'' IS DISTINCT FROM public.combat_v2_sha256(p_request)
 THEN RAISE EXCEPTION ''MANUAL_COUNTED_RESUME_ASYNC_OWNER'' USING ERRCODE=''42501'';END IF;
 IF EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit WHERE receipt_id=r.id AND event_code=''manual_counted_resume_v1'')
 OR w.state IS DISTINCT FROM ''claimed'' OR w.lease_id IS NULL OR w.lease_expires_at IS NULL OR w.lease_expires_at>clock_timestamp()
 THEN RETURN jsonb_build_object(''state'',w.state,''granted_now'',false,''work'',NULL,''count_reuse'',NULL);END IF;
 -- This continuation is the existing opening narration, not a new Director/role attempt.
 IF w.kind IS DISTINCT FROM ''narration'' OR w.payload->>''schema_version'' NOT IN(''mission-generic-narration/1'',''mission-generic-narration/2'')
 OR NOT EXISTS(SELECT 1 FROM mission_generic_owner.board_starts b WHERE b.master_session_id=w.master_session_id AND b.id=w.authority_receipt_id)
 OR w.authorization_id IS NOT NULL OR w.dispatch_id IS NOT NULL OR w.message_id IS NOT NULL OR w.finalized_at IS NOT NULL
 OR r.status IS DISTINCT FROM ''claimed'' OR r.dispatch_count IS DISTINCT FROM 0 OR r.finalized_at IS NOT NULL
 OR r.authority_receipt_id IS DISTINCT FROM w.id OR r.master_session_id IS DISTINCT FROM w.master_session_id
 OR r.request_key IS DISTINCT FROM w.request_key OR r.event_kind IS DISTINCT FROM ''mission_generic_event''
 OR r.renderer_version IS DISTINCT FROM ''mission-generic-runtime/1''
 OR EXISTS(SELECT 1 FROM mission_narrative_internal.provider_authorizations WHERE receipt_id=r.id)
 OR EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts WHERE receipt_id=r.id)
 OR EXISTS(SELECT 1 FROM staff_ai_quota_private.calls WHERE producer=''mission_generic_ai'' AND source_id=r.id AND call_no<>2)
 OR EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit WHERE receipt_id=r.id AND event_code NOT IN(''c1266_async_owner_v1'',''c8_count_started'',''c8_count_success''))
 THEN RAISE EXCEPTION ''MANUAL_COUNTED_RESUME_NO_GEN_PROOF'' USING ERRCODE=''42501'';END IF;
 SELECT count(*),jsonb_agg(details)->0 INTO n,sd FROM mission_narrative_internal.dispatch_audit WHERE receipt_id=r.id AND event_code=''c8_count_started'';
 IF n<>1 THEN RAISE EXCEPTION ''MANUAL_COUNTED_RESUME_COUNT_START'' USING ERRCODE=''40001'';END IF;
 SELECT count(*),jsonb_agg(details)->0 INTO n,pf FROM mission_narrative_internal.dispatch_audit WHERE receipt_id=r.id AND event_code=''c8_count_success'';
 IF n<>1 OR NOT mission_factory_owner.keys_exact_v2(pf,ARRAY[''schema_version'',''work_id'',''measurement_id'',''state'',''generation_request_sha256'',''input_tokens'',''max_input_tokens'',''policy_snapshot_sha256'',''generation_allowed'',''count_http_calls'',''generation_http_calls''])
 OR pf->>''schema_version'' IS DISTINCT FROM ''mission-generic-count-proof/1'' OR pf->>''state'' IS DISTINCT FROM ''success''
 OR pf->''generation_allowed'' IS DISTINCT FROM ''true''::jsonb OR pf->''count_http_calls'' IS DISTINCT FROM ''1''::jsonb OR pf->''generation_http_calls'' IS DISTINCT FROM ''0''::jsonb
 OR pf->>''work_id'' IS DISTINCT FROM w.id::text OR sd->>''work_id'' IS DISTINCT FROM w.id::text
 OR sd->>''lease_id'' IS DISTINCT FROM w.lease_id::text OR sd->>''measurement_id'' IS DISTINCT FROM pf->>''measurement_id''
 OR sd->>''generation_request_sha256'' IS DISTINCT FROM pf->>''generation_request_sha256''
 OR sd->>''generation_request_sha256'' IS DISTINCT FROM encode(extensions.digest(convert_to(sd->>''generation_request_text'',''UTF8''),''sha256''),''hex'')
 OR (sd->>''generation_request_bytes'')::integer IS DISTINCT FROM octet_length(sd->>''generation_request_text'')
 OR sd->>''provider_input_contract_version'' IS DISTINCT FROM ''mission-generic-provider-input/5''
 OR sd->>''execution_context'' IS DISTINCT FROM ''staff_mission''
 THEN RAISE EXCEPTION ''MANUAL_COUNTED_RESUME_COUNT_PROOF'' USING ERRCODE=''40001'';END IF;
 SELECT * INTO STRICT ct FROM staff_ai_quota_private.calls WHERE id=(sd->>''shared_count_ticket'')::uuid FOR UPDATE;
 IF ct.producer IS DISTINCT FROM ''mission_generic_ai'' OR ct.call_no IS DISTINCT FROM 2 OR ct.source_id IS DISTINCT FROM r.id
 OR ct.scope_id IS DISTINCT FROM w.master_session_id OR ct.state IS DISTINCT FROM ''unknown_billable''
 OR ct.reserved_usd IS DISTINCT FROM (sd->>''count_upper_cost_usd'')::numeric
 OR ct.model IS DISTINCT FROM sd#>>''{policy_snapshot,model}''
 OR sd->>''shared_count_source'' IS DISTINCT FROM r.id::text OR sd->>''shared_count_scope'' IS DISTINCT FROM w.master_session_id::text OR sd->>''shared_count_call_no'' IS DISTINCT FROM ''2''
 OR (SELECT count(*) FROM staff_ai_quota_private.calls WHERE producer=''mission_generic_ai'' AND source_id=r.id)<>1
 THEN RAISE EXCEPTION ''MANUAL_COUNTED_RESUME_COUNT_TICKET'' USING ERRCODE=''40001'';END IF;
 authority:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
 e:=mission_generic_owner.c1266_historical_work_v1(w.id);q:=mission_generic_owner.manual_staff_scope_v1(w.master_session_id);
 SELECT * INTO STRICT wc FROM mission_public_owner.work_contracts_v1 WHERE work_id=w.id;
 IF authority IS NULL OR authority->''runtime_authorized'' IS DISTINCT FROM ''true''::jsonb OR q IS NULL OR e IS NULL
 OR authority->>''execution_context'' IS DISTINCT FROM ''staff_mission''
 OR e->>''schema_version'' IS DISTINCT FROM ''c1266-work-execution-attestation/3''
 OR e->''admission'' IS DISTINCT FROM authority->''admission'' OR authority#>>''{admission,schema_version}'' IS DISTINCT FROM ''c1266-staff-admission-authority/3''
 OR e->>''binding_sha256'' IS DISTINCT FROM authority->>''binding_sha256''
 OR e->>''financial_qualification_sha256'' IS DISTINCT FROM authority->>''financial_qualification_sha256''
 OR e->>''c7_budget_qualification_sha256'' IS DISTINCT FROM authority->>''c7_budget_qualification_sha256''
 OR e->>''source_qualification_sha256'' IS DISTINCT FROM public.combat_v2_sha256(q)
 OR sd->>''admission_sha256'' IS DISTINCT FROM public.combat_v2_sha256(authority->''admission'')
 OR sd->>''c7_budget_qualification_sha256'' IS DISTINCT FROM authority->>''c7_budget_qualification_sha256''
 THEN RAISE EXCEPTION ''MANUAL_COUNTED_RESUME_AUTHORITY'' USING ERRCODE=''42501'';END IF;
 snap:=mission_generic_owner.c8_policy_snapshot_v1(w.id);
 IF sd->''policy_snapshot'' IS DISTINCT FROM snap OR sd->>''policy_snapshot_sha256'' IS DISTINCT FROM public.combat_v2_sha256(snap)
 OR pf->>''policy_snapshot_sha256'' IS DISTINCT FROM sd->>''policy_snapshot_sha256''
 OR pf->>''max_input_tokens'' IS DISTINCT FROM snap->>''max_input_tokens''
 OR (pf->>''input_tokens'')::integer<0 OR (pf->>''input_tokens'')::integer>(snap->>''max_input_tokens'')::integer
 THEN RAISE EXCEPTION ''MANUAL_COUNTED_RESUME_POLICY_DRIFT'' USING ERRCODE=''40001'';END IF;
 PERFORM mission_generic_owner.work_assert(w);PERFORM mission_generic_owner.role_dispatch_assert_v4(w.id);
 PERFORM mission_generic_owner.assert_runtime(w.master_session_id);PERFORM mission_generic_owner.provider_ready(w.id);
 old_work:=to_jsonb(w)-ARRAY[''lease_id'',''lease_expires_at''];old_receipt:=to_jsonb(r);old_contract:=to_jsonb(wc);old_ticket:=to_jsonb(ct);
 old_lease:=w.lease_id;old_until:=w.lease_expires_at;new_lease:=gen_random_uuid();new_until:=clock_timestamp()+interval ''360 seconds'';
 UPDATE mission_generic_owner.work_items SET lease_id=new_lease,lease_expires_at=new_until WHERE id=w.id AND state=''claimed'' AND lease_id=old_lease AND lease_expires_at=old_until RETURNING * INTO STRICT w;
 budget:=mission_generic_owner.c7_run_budget_v1(w.master_session_id,false,w.id);
 IF budget->''enforced'' IS DISTINCT FROM ''true''::jsonb OR budget->''allowed'' IS DISTINCT FROM ''true''::jsonb
 THEN RAISE EXCEPTION ''MANUAL_COUNTED_RESUME_BUDGET_CLOSED'' USING ERRCODE=''42501'';END IF;
 h:=jsonb_build_object(''schema_version'',''manual-counted-lease-handoff/1'',''work_id'',w.id,''master_session_id'',w.master_session_id,''event_id'',w.event_id,''request_key'',w.request_key,''revision'',w.revision,''payload_sha256'',w.payload_sha256,''binding_sha256'',w.definition_sha256,''dispatch_receipt_id'',r.id,''previous_lease_id'',old_lease,''previous_lease_expires_at'',old_until,''lease_id'',new_lease,''lease_expires_at'',new_until,''actor_user_id'',p_user,''contract_sha256'',wc.contract_sha256,''contract_release_sha256'',wc.release_sha256,''current_release_sha256'',authority->>''release_sha256'',''source_qualification_sha256'',e->>''source_qualification_sha256'',''count_start_sha256'',public.combat_v2_sha256(sd),''count_success_sha256'',public.combat_v2_sha256(pf),''count_ticket_sha256'',public.combat_v2_sha256(old_ticket),''generation_request_sha256'',sd->>''generation_request_sha256'',''generation_request_bytes'',sd->''generation_request_bytes'',''policy_snapshot_sha256'',sd->>''policy_snapshot_sha256'');
 INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) VALUES(r.id,''manual_counted_resume_v1'',h) RETURNING id INTO hid;
 IF mission_generic_owner.counted_resume_evidence_v1(w.id,new_lease) IS DISTINCT FROM h THEN RAISE EXCEPTION ''MANUAL_COUNTED_RESUME_HANDOFF_INVALID'' USING ERRCODE=''40001'';END IF;
 limits:=jsonb_build_object(''provider_calls_remaining'',1,''max_output_tokens'',20000,''max_input_bytes'',491520,''max_request_bytes'',1310720,''transport_max_chars'',5000,''provider_timeout_ms'',240000);
 dto:=jsonb_build_object(''schema_version'',''mission-generic-work/1'',''work_id'',w.id,''master_session_id'',w.master_session_id,''event_id'',w.event_id,''request_key'',w.request_key,''revision'',w.revision,''step_key'',w.step_key,''run_control_version'',w.run_control_version,''definition_sha256'',w.definition_sha256,''encounter_id'',w.encounter_id,''authority_receipt_id'',w.authority_receipt_id,''kind'',w.kind,''lease_id'',w.lease_id,''server_now'',clock_timestamp(),''lease_expires_at'',w.lease_expires_at,''payload_sha256'',w.payload_sha256,''payload'',w.payload,''limits'',limits,''narrative_admission'',wc.contract,''narrative_admission_sha256'',wc.contract_sha256,''provider_input_contract'',mission_generic_owner.c1266_provider_input_v1(w.id,limits),''narrative_profile'',wc.contract->>''editorial_profile'');
 reuse:=jsonb_build_object(''schema_version'',''mission-generic-count-reuse/1'',''work_id'',w.id,''previous_lease_id'',old_lease,''lease_id'',new_lease,''dispatch_receipt_id'',r.id,''resume_audit_id'',hid::text,''generation_request_bytes'',sd->''generation_request_bytes'',''count_proof'',pf);
 IF (to_jsonb(w)-ARRAY[''lease_id'',''lease_expires_at'']) IS DISTINCT FROM old_work
 OR (SELECT to_jsonb(x) FROM mission_narrative_internal.dispatch_receipts x WHERE id=r.id) IS DISTINCT FROM old_receipt
 OR (SELECT to_jsonb(x) FROM mission_public_owner.work_contracts_v1 x WHERE work_id=w.id) IS DISTINCT FROM old_contract
 OR (SELECT to_jsonb(x) FROM staff_ai_quota_private.calls x WHERE id=ct.id) IS DISTINCT FROM old_ticket
 OR (SELECT details FROM mission_narrative_internal.dispatch_audit WHERE receipt_id=r.id AND event_code=''c8_count_started'') IS DISTINCT FROM sd
 OR (SELECT details FROM mission_narrative_internal.dispatch_audit WHERE receipt_id=r.id AND event_code=''c8_count_success'') IS DISTINCT FROM pf
 THEN RAISE EXCEPTION ''MANUAL_COUNTED_RESUME_HISTORY_DRIFT'' USING ERRCODE=''40001'';END IF;
 RETURN jsonb_build_object(''state'',''claimed'',''granted_now'',true,''work'',dto,''count_reuse'',reuse);
END $function$
';
 EXECUTE 'CREATE OR REPLACE FUNCTION mission_generic_owner.staff_journal_settlements_v1(p_session uuid, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''''
AS $function$
DECLARE result jsonb;
BEGIN
 -- This private reader is called only from the already authenticated room projection.
 -- Settled collective publications are readable by each current Staff participant;
 -- they confer no owner, retry, claim, tick, provider or gameplay authority.
 IF p_session IS NULL OR p_user IS NULL OR NOT EXISTS(
  SELECT 1 FROM public.master_v2_sessions s JOIN public.locations l ON l.id=s.location_id
  JOIN public.master_v2_participants mp ON mp.session_id=s.id AND mp.user_id_snapshot=p_user
   AND mp.left_at IS NULL AND mp.engagement_state=''attivo''
  JOIN public.characters ch ON ch.id=mp.character_id AND ch.user_id=mp.user_id_snapshot
  JOIN public.profiles pr ON pr.id=p_user AND pr.role IN(''admin'',''master'')
  WHERE s.id=p_session AND s.owner_kind=''ai_service'' AND s.master_user IS NULL
   AND s.location_id=''0b85f354-9cdb-47e1-baf9-3d266bb7e06b''::uuid
   AND l.is_active AND l.is_test AND s.closed_at IS NULL AND s.suspended_at IS NULL
   AND s.stato=''in_corso'')
  OR mission_generic_owner.manual_staff_scope_v1(p_session) IS NULL THEN RETURN NULL;END IF;
 WITH released AS MATERIALIZED(
  SELECT w.id AS work_id,w.receipt_id,w.result_sha256,
   jsonb_build_object(''schema_version'',''mission-generic-request/1'',''master_session_id'',w.master_session_id,
    ''event_id'',w.event_id,''request_key'',w.request_key,''expected_revision'',w.revision) AS request,
   sw.context->>''source_revision'' AS source_revision,
   jsonb_build_object(''source_window_id'',sw.id,''source_revision'',sw.context->>''source_revision'',
    ''reason'',sw.superseded_reason,''audit_sha256'',public.combat_v2_sha256(a.details)) AS release
  FROM mission_generic_owner.work_items w
  JOIN mission_generic_owner.unified_source_windows sw ON sw.id=w.authority_receipt_id
   AND sw.work_id=w.id AND sw.master_session_id=w.master_session_id
  JOIN mission_narrative_internal.dispatch_receipts dr ON dr.id=w.dispatch_receipt_id
   AND dr.master_session_id=w.master_session_id AND dr.authority_receipt_id=w.id
   AND dr.request_key=w.request_key AND dr.status=''failed'' AND dr.dispatch_count=0
   AND dr.finalized_at IS NOT NULL AND dr.charged_cost_usd=0 AND dr.upper_bound_cost_usd=0
  JOIN mission_narrative_internal.dispatch_audit a ON a.receipt_id=dr.id
   AND a.event_code=''staff_preprovider_request_retry''
   AND ((w.id=''d460a7be-a3a2-4ad8-9d3b-d2e929f2947e''::uuid AND a.details->>''schema_version''=''c1266-request-size-release/1'') OR (w.id=''f4f7185e-4aae-4edd-ac24-65f8dcfa36f5''::uuid AND a.details->>''schema_version''=''c1266-turn-recovery-release/1''))
   AND a.details->>''work_id''=w.id::text AND a.details->>''source_window_id''=sw.id::text
  WHERE p_session=''44078c5f-7001-4129-9506-e2f34e68c8ac''::uuid
   AND w.master_session_id=p_session AND w.id IN(''d460a7be-a3a2-4ad8-9d3b-d2e929f2947e''::uuid,''f4f7185e-4aae-4edd-ac24-65f8dcfa36f5''::uuid)
   AND w.state=''failed'' AND w.kind=''director'' AND w.finalized_at IS NOT NULL
   AND w.receipt_id IS NOT NULL AND w.message_id IS NULL
   AND w.result_sha256=public.combat_v2_sha256(w.result)
   AND w.payload_sha256=public.combat_v2_sha256(w.payload)
   AND sw.context->>''source_revision''~''^[a-f0-9]{64}$''
   AND sw.superseded_reason=''staff_preprovider_request_retry''
   AND mission_generic_owner.role_source_released_v4(sw.id)
 ),
 candidates AS MATERIALIZED(
  SELECT w.*,jsonb_build_object(''schema_version'',''mission-generic-request/1'',''master_session_id'',w.master_session_id,
   ''event_id'',w.event_id,''request_key'',w.request_key,''expected_revision'',w.revision) AS request
  FROM mission_generic_owner.work_items w
  WHERE w.master_session_id=p_session AND (w.state=''completed'' OR (w.id=''e366b9fa-54dc-4abd-8ba6-9ceee83be9a4''::uuid AND w.state=''failed'' AND w.kind=''director''
   AND w.result_sha256=''d0a4266f89198307e8c9020af67b4d2b099edc1cbf20e0aea5b38d1b78fc8ea9''
   AND public.combat_v2_sha256(w.result)=''674c8253e511750022b6d9b477383aed5743ffb2c9ceee7b35a0125c10ac6201''
   AND w.receipt_id=''07366817-3bf6-4bad-8387-0a4c0d1804f7''::uuid AND w.dispatch_receipt_id=''e9524086-1e03-42d8-866b-1c12eb77840a''::uuid
   AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit aa JOIN mission_generic_owner.unified_batches ab ON ab.decision_work_id=w.id AND ab.master_session_id=p_session
    WHERE aa.receipt_id=w.dispatch_receipt_id AND aa.event_code=''c1266_saved_director_applied''
     AND aa.details->>''schema_version''=''c1266-saved-director-application/1'' AND aa.details->>''master_session_id''=p_session::text
     AND aa.details->>''work_id''=w.id::text AND aa.details->>''batch_id''=ab.id::text AND aa.details->>''writer_work_id''=ab.writer_work_id::text
     AND aa.details->>''result_sha256''=w.result_sha256 AND aa.details->>''generation_http_calls''=''0'' AND aa.details->>''failed_work_preserved''=''true''
     AND ab.state=''published'' AND ab.published_at IS NOT NULL AND ab.message_id IS NOT NULL))) AND w.kind IN(''director'',''narration'')
   AND w.finalized_at IS NOT NULL AND w.receipt_id IS NOT NULL
   AND w.result_sha256 ~ ''^[0-9a-f]{64}$'' AND w.payload_sha256=public.combat_v2_sha256(w.payload)
  ORDER BY w.created_at DESC,w.id LIMIT 128
 ), qualified AS MATERIALIZED(
  SELECT w.* FROM candidates w
  JOIN mission_narrative_internal.dispatch_receipts dr ON dr.id=w.dispatch_receipt_id
   AND dr.master_session_id=w.master_session_id AND dr.authority_receipt_id=w.id
   AND dr.request_key=w.request_key AND dr.status=''success'' AND dr.finalized_at IS NOT NULL
   AND dr.event_kind=''mission_generic_event'' AND dr.renderer_version=''mission-generic-runtime/1''
   AND dr.request_fingerprint=mission_internal.fingerprint(w.request)
   AND dr.envelope_sha256=public.combat_v2_sha256(dr.envelope) AND dr.authority_sha256=dr.envelope_sha256
   AND dr.envelope->>''work_id''=w.id::text AND dr.envelope->>''master_session_id''=p_session::text
   AND dr.envelope->>''event_id''=w.event_id::text AND dr.envelope->>''authority_receipt_id''=w.authority_receipt_id::text
   AND dr.envelope->>''payload_sha256''=w.payload_sha256 AND dr.envelope->>''definition_sha256''=w.definition_sha256
   AND dr.envelope->''revision''=to_jsonb(w.revision)
  WHERE mission_generic_owner.c1266_historical_work_v1(w.id)->>''execution_context''=''staff_mission''
   AND 1=(SELECT count(*) FROM mission_narrative_internal.dispatch_audit a
    WHERE a.receipt_id=dr.id AND a.event_code=''c1266_async_owner_v1''
     AND mission_factory_owner.keys_exact_v2(a.details,ARRAY[''schema_version'',''actor_user_id'',''work_id'',''request_sha256'',''envelope_sha256'',''provider_timeout_ms''])
     AND a.details->>''schema_version''=''mission-generic-async-owner/1''
     AND a.details->>''work_id''=w.id::text AND a.details->>''request_sha256''=public.combat_v2_sha256(w.request)
     AND a.details->>''envelope_sha256''=dr.envelope_sha256 AND a.details->''provider_timeout_ms''=''240000''::jsonb)
 ), published AS MATERIALIZED(
  SELECT w.id AS writer_work_id,w.receipt_id,w.result_sha256,w.message_id
  FROM qualified w JOIN public.messages msg ON msg.id=w.message_id
   AND msg.location_id=''0b85f354-9cdb-47e1-baf9-3d266bb7e06b''::uuid
   AND msg.kind=''fato'' AND msg.recipient_user IS NULL AND msg.body=w.result->>''text''
  WHERE w.kind=''narration'' AND (
   EXISTS(SELECT 1 FROM mission_generic_owner.unified_batches ub
    JOIN mission_generic_owner.unified_source_windows sw ON sw.id=ub.source_window_id
     AND sw.master_session_id=p_session AND sw.consumed_message_id=w.message_id
    WHERE ub.id=w.authority_receipt_id AND ub.master_session_id=p_session AND ub.writer_work_id=w.id
     AND ub.state=''published'' AND ub.published_at IS NOT NULL AND ub.message_id=w.message_id)
   OR EXISTS(SELECT 1 FROM mission_generic_owner.board_starts bs
    JOIN public.mission_run_publications pub ON pub.master_session_id=bs.master_session_id AND pub.event_id=bs.event_id
    JOIN public.mission_run_outbox ob ON ob.publication_id=pub.id AND ob.master_session_id=p_session AND ob.event_id=bs.event_id
     AND ob.state=''published'' AND ob.published_at IS NOT NULL
    WHERE bs.master_session_id=p_session AND bs.id=w.event_id AND bs.id=w.authority_receipt_id
     AND bs.id::text=w.payload->>''opening_start_receipt_id'' AND bs.state=''published'' AND bs.published_at IS NOT NULL
     AND bs.result->>''master_session_id''=p_session::text AND bs.result->>''event_id''=bs.event_id::text
     AND bs.result->>''start_receipt_id''=bs.id::text
     AND pub.context_fingerprint=bs.result->>''context_fingerprint'' AND ob.context_fingerprint=pub.context_fingerprint
     AND pub.status=''committed''
     AND pub.body_sha256=encode(extensions.digest(convert_to(msg.body,''UTF8''),''sha256''),''hex'')))
 ), settled_raw AS MATERIALIZED(
  SELECT w.request,w.id AS work_id,w.receipt_id,w.result_sha256,
   jsonb_build_object(''writer_work_id'',p.writer_work_id,''message_id'',p.message_id,''receipt_id'',p.receipt_id,''result_sha256'',p.result_sha256) AS publication
  FROM qualified w JOIN published p ON p.writer_work_id=w.id WHERE w.kind=''narration''
  UNION ALL
  SELECT w.request,w.id,w.receipt_id,w.result_sha256,
   jsonb_build_object(''writer_work_id'',p.writer_work_id,''message_id'',p.message_id,''receipt_id'',p.receipt_id,''result_sha256'',p.result_sha256)
  FROM qualified w
  JOIN mission_generic_owner.unified_source_windows sw ON sw.work_id=w.id AND sw.id=w.authority_receipt_id
   AND sw.master_session_id=p_session AND sw.consumed_message_id IS NOT NULL AND sw.superseded_at IS NULL
  JOIN mission_generic_owner.unified_batches ub ON ub.source_window_id=sw.id AND ub.decision_work_id=w.id
   AND ub.master_session_id=p_session AND ub.state=''published'' AND ub.published_at IS NOT NULL
   AND ub.message_id=sw.consumed_message_id
  JOIN published p ON p.writer_work_id=ub.writer_work_id AND p.message_id=sw.consumed_message_id
  WHERE w.kind=''director''
 ), settled AS MATERIALIZED(
  SELECT DISTINCT s.* FROM settled_raw s WHERE 1=(SELECT count(DISTINCT check_s.publication)
   FROM settled_raw check_s WHERE check_s.work_id=s.work_id AND check_s.request=s.request)
 ), items AS(
  SELECT jsonb_build_object(''selector'',jsonb_build_object(''kind'',''request'',''request'',s.request),
   ''request'',s.request,''work_id'',s.work_id,''receipt_id'',s.receipt_id,''result_sha256'',s.result_sha256,''publication'',s.publication) AS item
  FROM settled s
  UNION ALL
  SELECT jsonb_build_object(''selector'',jsonb_build_object(''kind'',''staff_tick'',''source_revision'',t.source_revision),
   ''request'',s.request,''work_id'',s.work_id,''receipt_id'',s.receipt_id,''result_sha256'',s.result_sha256,''publication'',s.publication)
  FROM mission_generic_owner.staff_progress_ticks_v1 t
  JOIN mission_generic_owner.progress_receipts pr
   ON pr.master_session_id=p_session AND pr.actor_user_id=t.actor_user_id
   AND pr.result_sha256=public.combat_v2_sha256(pr.result)
   AND (
    (pr.request_key=t.request_key AND pr.result_sha256=t.result_sha256)
    OR EXISTS(
     SELECT 1 FROM released rel
     JOIN mission_generic_owner.progress_receipts original_pr ON original_pr.request_key=t.request_key
      AND original_pr.master_session_id=p_session AND original_pr.actor_user_id=t.actor_user_id
      AND original_pr.result_sha256=t.result_sha256
      AND original_pr.result_sha256=public.combat_v2_sha256(original_pr.result)
      AND original_pr.result->>''schema_version''=''mission-generic-progress/1''
      AND original_pr.result->>''master_session_id''=p_session::text
      AND original_pr.result->''dispatch''=rel.request
     WHERE rel.source_revision=t.source_revision
      AND pr.request_key=mission_ai_service_owner.uuid5(rel.work_id,
       ''mission-staff-released-director-retry/1:''||t.source_revision)))
   AND pr.result->>''schema_version''=''mission-generic-progress/1'' AND pr.result->>''master_session_id''=p_session::text
  JOIN settled s ON s.request=pr.result->''dispatch''
  JOIN mission_generic_owner.unified_source_windows sw ON sw.work_id=s.work_id AND sw.master_session_id=p_session
   AND sw.context->>''source_revision''=t.source_revision AND sw.consumed_message_id=(s.publication->>''message_id'')::uuid
  WHERE t.master_session_id=p_session AND t.source_revision ~ ''^[0-9a-f]{64}$''
   AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=t.staff_user_id AND p.role IN(''admin'',''master''))

  UNION ALL
  SELECT jsonb_build_object(''selector'',jsonb_build_object(''kind'',''request'',''request'',rel.request),
   ''request'',rel.request,''work_id'',rel.work_id,''receipt_id'',rel.receipt_id,''result_sha256'',rel.result_sha256,''release'',rel.release)
  FROM released rel
  UNION ALL
  SELECT jsonb_build_object(''selector'',jsonb_build_object(''kind'',''staff_tick'',''source_revision'',t.source_revision),
   ''request'',rel.request,''work_id'',rel.work_id,''receipt_id'',rel.receipt_id,''result_sha256'',rel.result_sha256,''release'',rel.release)
  FROM released rel
  JOIN mission_generic_owner.staff_progress_ticks_v1 t ON t.master_session_id=p_session AND t.source_revision=rel.source_revision
  JOIN mission_generic_owner.progress_receipts pr ON pr.request_key=t.request_key
   AND pr.master_session_id=p_session AND pr.actor_user_id=t.actor_user_id
   AND pr.result_sha256=t.result_sha256 AND pr.result_sha256=public.combat_v2_sha256(pr.result)
   AND pr.result->''dispatch''=rel.request
 ), bounded AS(SELECT DISTINCT item FROM items ORDER BY item LIMIT 128)
 SELECT jsonb_build_object(''schema_version'',CASE WHEN EXISTS(SELECT 1 FROM released) THEN ''mission-journal-settlements/2'' ELSE ''mission-journal-settlements/1'' END,''master_session_id'',p_session,
  ''items'',coalesce(jsonb_agg(item ORDER BY item),''[]''::jsonb)) INTO result FROM bounded;
 RETURN result;
END $function$

';
 EXECUTE 'CREATE OR REPLACE FUNCTION mission_generic_owner.c1266_provider_input_v1(p_work uuid, p_limits jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
DECLARE w mission_generic_owner.work_items; b mission_generic_owner.run_bindings;
 a mission_generic_owner.dispatch_admissions; authority jsonb; admission jsonb;
 snapshot jsonb; narrative jsonb;scope jsonb;max_input integer;max_request integer;continuation6 jsonb;
 scene_policy_cached jsonb;scene_policy_final jsonb;
BEGIN
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work;
 authority:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
 IF authority IS NULL OR authority->>''runtime_authorized'' IS DISTINCT FROM ''true''
 THEN RAISE EXCEPTION ''C1266_PROVIDER5_RUNTIME_AUTHORITY_REQUIRED'' USING ERRCODE=''42501'';END IF;
 SELECT * INTO STRICT b FROM mission_generic_owner.run_bindings WHERE master_session_id=w.master_session_id;
 SELECT * INTO STRICT a FROM mission_generic_owner.dispatch_admissions WHERE master_session_id=w.master_session_id;
 snapshot:=mission_generic_owner.c8_policy_snapshot_v1(w.id);
 -- Reuse only the policy qualified by the original C8 builder in this invocation.
 scene_policy_cached:=snapshot->''scene_policy'';
 IF scene_policy_cached IS NOT NULL AND (
  snapshot->>''schema_version'' IS DISTINCT FROM ''c1266-staff-scene-count-snapshot/2''
  OR scene_policy_cached IS DISTINCT FROM ''{"mode":"staff_scene_uncapped","maxCount":null,"maxGen":null,"maxHTTP":null,"maxUSD":null}''::jsonb
  OR snapshot->>''scene_policy_sha256'' IS DISTINCT FROM public.combat_v2_sha256(scene_policy_cached)
  OR snapshot->>''scene_policy_contract_sha256'' IS DISTINCT FROM ''1564720ca33bc961ff26fc15e07bd364ebd41a60b7a5a48c970a9c100038fad6''
  OR snapshot->>''release_sha256'' IS DISTINCT FROM authority->>''release_sha256'')
 THEN RAISE EXCEPTION ''C1266_PROVIDER_POLICY_MEMO_BINDING'' USING ERRCODE=''40001'';END IF;
 narrative:=mission_public_owner.work_contract_v1(w.id);
 -- Historical contract bytes stay sealed. A current named continuation
 -- proves compatibility before selecting its original transport authority.
 IF narrative IS NOT NULL AND narrative->>''release_sha256'' IS DISTINCT FROM authority->>''release_sha256'' THEN
  continuation6:=CASE WHEN authority#>>''{admission,schema_version}''=''c1266-staff-admission-authority/3''
   THEN mission_generic_owner.counted_resume_evidence_v1(w.id,w.lease_id)
   ELSE mission_generic_owner.c1266_opening_continuation_v1(w.id) END;
  IF continuation6 IS NULL OR continuation6->>''current_release_sha256'' IS DISTINCT FROM authority->>''release_sha256''
  OR continuation6->>''contract_sha256'' IS DISTINCT FROM public.combat_v2_sha256(narrative)
  THEN RAISE EXCEPTION ''C1266_CONTINUATION_AUTHORITY_REQUIRED'' USING ERRCODE=''42501'';END IF;
  authority:=jsonb_set(jsonb_set(authority,''{release_sha256}'',narrative->''release_sha256''),''{admission}'',narrative#>''{source_attestation,execution_authority,admission}'');
 END IF;
 admission:=authority->''admission'';
 IF (w.kind IN(''choice'',''director'',''narration'')) IS DISTINCT FROM TRUE OR w.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.payload)
  OR b.snapshot_sha256 IS DISTINCT FROM mission_internal.fingerprint(b.snapshot)
  OR w.definition_sha256 IS DISTINCT FROM b.snapshot_sha256
  OR a.enabled IS DISTINCT FROM TRUE OR a.c7_budget_enforced IS DISTINCT FROM TRUE
  OR a.call_limit IS DISTINCT FROM 14 OR a.cost_budget_usd IS DISTINCT FROM 0.3136
  OR a.c8_count_upper_cost_usd IS DISTINCT FROM 0.0124
  OR (a.c8_count_qualification_sha256 ~ ''^[0-9a-f]{64}$'') IS DISTINCT FROM TRUE
  OR authority->>''financial_qualification_sha256'' IS DISTINCT FROM a.c8_count_qualification_sha256
  OR (authority->>''release_sha256'' ~ ''^[0-9a-f]{64}$'') IS DISTINCT FROM TRUE
  OR snapshot->>''policy_version'' IS DISTINCT FROM ''2'' OR snapshot->>''max_input_tokens'' IS DISTINCT FROM ''24000''
  OR snapshot->>''max_output_tokens'' IS DISTINCT FROM ''20000'' OR snapshot->>''model'' IS DISTINCT FROM ''gpt-6-luna''
  OR snapshot->>''reasoning_effort'' IS DISTINCT FROM ''high'' OR snapshot->>''store'' IS DISTINCT FROM ''false''
  OR (snapshot->>''input_usd_million'')::numeric IS DISTINCT FROM 0.1 OR (snapshot->>''output_usd_million'')::numeric IS DISTINCT FROM 0.5
 THEN RAISE EXCEPTION ''C1266_PROVIDER5_WORK_POLICY_BINDING'' USING ERRCODE=''40001'';END IF;
 IF authority->>''execution_context''=''staff_mission'' AND admission->>''schema_version''=''c1266-staff-admission-authority/3'' THEN
  DECLARE mq jsonb:=mission_generic_owner.manual_staff_scope_v1(w.master_session_id);
  BEGIN
   IF mq IS NULL OR admission IS DISTINCT FROM jsonb_build_object(''schema_version'',''c1266-staff-admission-authority/3'',''kind'',''staff_finite'',''resource_scope'',''staff_simulation'',''finite_admission_sha256'',public.combat_v2_sha256(mq),''admission_id'',mq->>''start_receipt_id'',''location_id'',mq->>''location_id'')
   OR scene_policy_cached IS NOT NULL THEN RAISE EXCEPTION ''MANUAL_STAFF_PROVIDER_ADMISSION'' USING ERRCODE=''42501'';END IF;
  END;
 ELSIF authority->>''execution_context''=''staff_mission'' THEN
   IF (NOT mission_factory_owner.keys_exact_v2(admission,ARRAY[''schema_version'',''kind'',''resource_scope'',''finite_admission_sha256'',''grant_id'',''not_before'',''expires_at'',''location_id''])
   OR admission->>''schema_version'' IS DISTINCT FROM ''c1266-staff-admission-authority/1''
   OR admission->>''kind'' IS DISTINCT FROM ''staff_finite'' OR admission->>''resource_scope'' IS DISTINCT FROM ''staff_simulation'') AND NOT ((mission_factory_owner.keys_exact_v2(admission,ARRAY[''schema_version'',''kind'',''resource_scope'',''finite_admission_sha256'',''grant_id'',''not_before'',''expires_at'',''location_id'',''campaign_id'',''time_policy'']) AND admission->>''schema_version''=''c1266-staff-admission-authority/2'' AND admission->>''kind''=''staff_finite'' AND admission->>''resource_scope''=''staff_simulation'' AND admission->>''campaign_id''=''b2fc5e28-072b-41f2-8dd8-cb5a35a13092'' AND admission->>''grant_id''=''b925043a-c1b3-434b-8fb4-f335903b2af0'' AND admission->>''not_before''=''2026-10-20T14:12:18.393948+00:00'' AND admission->>''expires_at''=''2026-10-20T15:12:18.393948+00:00'' AND admission->>''location_id''=''0b85f354-9cdb-47e1-baf9-3d266bb7e06b'' AND admission->''time_policy''=''{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}''::jsonb AND (admission->>''finite_admission_sha256'' ~ ''^[a-f0-9]{64}$'') IS TRUE) IS TRUE)
  THEN RAISE EXCEPTION ''C1266_PROVIDER5_STAFF_CLOSED8'';END IF;
 ELSIF authority->>''execution_context''=''ordinary_mission'' THEN
  IF NOT mission_factory_owner.keys_exact_v2(admission,ARRAY[''schema_version'',''kind'',''resource_scope'',''ordinary_admission_sha256'',''source_mission_id'',''source_plan_version_id'',''source_definition_id'',''source_plan_sha256'',''source_definition_sha256'',''source_sha256'',''location_id'',''start_receipt_id'',''roster_snapshot_sha256'',''eligibility_receipt_sha256'',''protection''])
   OR admission->>''schema_version'' IS DISTINCT FROM ''c1266-ordinary-admission-authority/1''
   OR admission->>''kind'' IS DISTINCT FROM ''ordinary_authenticated''
   OR (admission->>''resource_scope'' IN(''world'',''staff_simulation'')) IS DISTINCT FROM TRUE
  THEN RAISE EXCEPTION ''C1266_PROVIDER5_ORDINARY_CLOSED15'';END IF;
  IF admission->>''resource_scope''=''world'' THEN
   IF NOT mission_factory_owner.keys_exact_v2(admission->''protection'',ARRAY[''schema_version'',''kind''])
    OR admission#>>''{protection,schema_version}'' IS DISTINCT FROM ''c1266-ordinary-protection/1''
    OR admission#>>''{protection,kind}'' IS DISTINCT FROM ''world''
   THEN RAISE EXCEPTION ''C1266_PROVIDER5_WORLD_PROTECTION_CLOSED2'';END IF;
  ELSE
   IF NOT mission_factory_owner.keys_exact_v2(admission->''protection'',ARRAY[''schema_version'',''kind'',''existing_qa_receipt_sha256'',''location_id'',''roster_snapshot_sha256''])
    OR admission#>>''{protection,schema_version}'' IS DISTINCT FROM ''c1266-ordinary-protection/1''
    OR admission#>>''{protection,kind}'' IS DISTINCT FROM ''existing_staff_simulation''
    OR (admission#>>''{protection,existing_qa_receipt_sha256}'' ~ ''^[0-9a-f]{64}$'') IS DISTINCT FROM TRUE
    OR admission#>>''{protection,location_id}'' IS DISTINCT FROM admission->>''location_id''
    OR admission#>>''{protection,roster_snapshot_sha256}'' IS DISTINCT FROM admission->>''roster_snapshot_sha256''
   THEN RAISE EXCEPTION ''C1266_PROVIDER5_PROTECTED_ORDINARY_CLOSED5'';END IF;
  END IF;
 ELSE RAISE EXCEPTION ''C1266_PROVIDER5_EXECUTION_CONTEXT'' USING ERRCODE=''42501'';END IF;
 IF (narrative IS NULL AND w.kind IN(''director'',''narration'')) OR (narrative IS NOT NULL AND(
  narrative->>''schema_version'' IS DISTINCT FROM ''mission-narrative-admission/3''
  OR narrative->>''master_session_id'' IS DISTINCT FROM w.master_session_id::text
  OR narrative->>''work_id'' IS DISTINCT FROM w.id::text
  OR narrative->>''release_sha256'' IS DISTINCT FROM authority->>''release_sha256''))
 THEN RAISE EXCEPTION ''C1266_PROVIDER5_NARRATIVE_ADMISSION_REQUIRED'' USING ERRCODE=''42501'';END IF;
 IF jsonb_typeof(p_limits) IS DISTINCT FROM ''object'' OR jsonb_typeof(p_limits->''max_input_bytes'') IS DISTINCT FROM ''number''
  OR jsonb_typeof(p_limits->''max_request_bytes'') IS DISTINCT FROM ''number''
  OR p_limits->>''max_output_tokens'' IS DISTINCT FROM ''20000''
 THEN RAISE EXCEPTION ''C1266_PROVIDER5_BYTE_SHAPE'' USING ERRCODE=''22023'';END IF;
 max_input:=(p_limits->>''max_input_bytes'')::integer;max_request:=(p_limits->>''max_request_bytes'')::integer;
 -- Conserva la differenza dei limiti di trasporto già presente nei due profili.
 IF max_input<=0 OR max_request<=0
  OR (mission_generic_owner.capacity()->>''input_capacity_bytes'')::integer IS NULL
  OR max_input>(10*(CASE WHEN admission->>''kind''=''staff_finite'' THEN CASE WHEN w.kind=''director'' THEN 65536 ELSE 49152 END ELSE least(49152,(mission_generic_owner.capacity()->>''input_capacity_bytes'')::integer) END))
  OR max_request>(10*(CASE WHEN admission->>''kind''=''staff_finite'' THEN CASE WHEN w.kind=''director'' AND authority->>''runtime_authorized''=''true'' AND authority->>''execution_context''=''staff_mission'' AND authority#>>''{admission,kind}''=''staff_finite'' AND authority#>>''{admission,resource_scope}''=''staff_simulation'' AND scene_policy_cached IS NOT NULL AND narrative->>''editorial_profile''=''cinematic_master_1'' THEN 98304 WHEN w.kind=''narration'' THEN 131072 ELSE 65536 END ELSE least(65536,(mission_generic_owner.capacity()->>''input_capacity_bytes'')::integer) END))
 THEN RAISE EXCEPTION ''C1266_PROVIDER5_BYTE_BOUND'' USING ERRCODE=''22023'';END IF;
 scope:=jsonb_build_object(''schema_version'',''c1266-mission-work-scope/2'',''execution_context'',authority->>''execution_context'',
  ''master_session_id'',w.master_session_id,''work_id'',w.id,''event_id'',w.event_id,''request_key'',w.request_key,''revision'',w.revision,
  ''authority_receipt_id'',w.authority_receipt_id,''definition_sha256'',w.definition_sha256,''payload_sha256'',w.payload_sha256,
  ''payload_schema_version'',w.payload->>''schema_version'',''run_control_version'',w.run_control_version,
  ''narrative_admission_sha256'',CASE WHEN narrative IS NOT NULL THEN public.combat_v2_sha256(narrative) END,''release_sha256'',authority->>''release_sha256'',
  ''admission'',admission,''policy_snapshot_sha256'',public.combat_v2_sha256(snapshot),''financial_qualification_sha256'',a.c8_count_qualification_sha256);
 -- Preserve the original live final validation, including every transitive guard.
 scene_policy_final:=mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id);
 IF scene_policy_final IS DISTINCT FROM scene_policy_cached
 THEN RAISE EXCEPTION ''C1266_PROVIDER_POLICY_DRIFT'' USING ERRCODE=''40001'';END IF;
 IF scene_policy_cached IS NOT NULL THEN
 scope:=jsonb_set(scope,''{schema_version}'',''"c1266-mission-work-scope/3"''::jsonb)||jsonb_build_object(''scene_policy'',scene_policy_cached,''scene_policy_sha256'',public.combat_v2_sha256(scene_policy_cached),''scene_policy_contract_sha256'',''1564720ca33bc961ff26fc15e07bd364ebd41a60b7a5a48c970a9c100038fad6'');
 RETURN jsonb_build_object(''schema_version'',''mission-generic-provider-input/6'',''input_tokens_limit'',24000,''policy_version'',2,''http_calls_per_generation'',2,''scope'',scope,''pricing'',jsonb_build_object(''model'',''gpt-6-luna'',''reasoning_effort'',''high'',''store'',false,''max_output_tokens'',20000,''input_usd_million'',0.1,''output_usd_million'',0.5,''count_upper_cost_usd'',''0.0124'',''generation_upper_cost_usd'',''0.0124''),''byte_bounds'',jsonb_build_object(''max_input_bytes'',max_input,''max_request_bytes'',max_request));END IF;
 RETURN jsonb_build_object(''schema_version'',''mission-generic-provider-input/5'',''input_tokens_limit'',24000,''policy_version'',2,''http_calls_per_generation'',2,
  ''scope'',scope,''pricing'',jsonb_build_object(''model'',''gpt-6-luna'',''reasoning_effort'',''high'',''store'',false,''max_output_tokens'',20000,
   ''input_usd_million'',0.1,''output_usd_million'',0.5,''count_upper_cost_usd'',''0.0124'',''generation_upper_cost_usd'',''0.0124''),
  ''byte_bounds'',jsonb_build_object(''max_input_bytes'',max_input,''max_request_bytes'',max_request));
END $function$
';
 EXECUTE 'SELECT jsonb_object_agg(v.signature,jsonb_build_object(''signature'',v.signature,''oid'',p.oid::bigint,''owner'',pg_get_userbyid(p.proowner),''acl'',p.proacl::text,''config'',to_jsonb(p.proconfig),''secdef'',p.prosecdef,''volatility'',p.provolatile::text,''language'',l.lanname,''source_md5'',md5(p.prosrc),''ddl_md5'',md5(pg_get_functiondef(p.oid)))) FROM (VALUES (''public.mission_generic_opening_claim_resume_v1(uuid,jsonb,jsonb)''),(''public.mission_generic_staff_republish_failed_v1(uuid,uuid,uuid)''),(''public.mission_generic_dispatch_claim_v1(uuid,jsonb)''),(''mission_generic_owner.unified_director_commit(uuid,jsonb)''),(''mission_generic_owner.unified_batch_payload(uuid)''),(''public.mission_generic_counted_resume_v1(uuid,jsonb)''),(''mission_generic_owner.staff_journal_settlements_v1(uuid,uuid)''),(''mission_generic_owner.c1266_provider_input_v1(uuid,jsonb)'')) v(signature) JOIN pg_proc p ON p.oid=to_regprocedure(v.signature) JOIN pg_language l ON l.oid=p.prolang' INTO heads;
 IF ((SELECT count(*) FROM jsonb_object_keys(heads))=8) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'RAW_RECOVERY_HEADER_COUNT' USING ERRCODE='40001';END IF;
 IF (((heads->'public.mission_generic_opening_claim_resume_v1(uuid,jsonb,jsonb)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres,service_role=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":true,"signature":"public.mission_generic_opening_claim_resume_v1(uuid,jsonb,jsonb)","source_md5":"3897710099b83a41c0839d34949add7f","volatility":"v"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_ATTRS' USING ERRCODE='40001';END IF;
 IF ((heads->'public.mission_generic_opening_claim_resume_v1(uuid,jsonb,jsonb)')->>'oid'='325618') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_OID' USING ERRCODE='40001';END IF;
 IF (((heads->'public.mission_generic_staff_republish_failed_v1(uuid,uuid,uuid)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres,service_role=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":true,"signature":"public.mission_generic_staff_republish_failed_v1(uuid,uuid,uuid)","source_md5":"10520878bf906beb89d1e37f2e473088","volatility":"v"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_ATTRS' USING ERRCODE='40001';END IF;
 IF ((heads->'public.mission_generic_staff_republish_failed_v1(uuid,uuid,uuid)')->>'oid'='150538') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_OID' USING ERRCODE='40001';END IF;
 IF (((heads->'public.mission_generic_dispatch_claim_v1(uuid,jsonb)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres,service_role=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":true,"signature":"public.mission_generic_dispatch_claim_v1(uuid,jsonb)","source_md5":"4cc1c02d651e0a6b39dd93541e65674c","volatility":"v"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_ATTRS' USING ERRCODE='40001';END IF;
 IF ((heads->'public.mission_generic_dispatch_claim_v1(uuid,jsonb)')->>'oid'='50410') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_OID' USING ERRCODE='40001';END IF;
 IF (((heads->'mission_generic_owner.unified_director_commit(uuid,jsonb)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":true,"signature":"mission_generic_owner.unified_director_commit(uuid,jsonb)","source_md5":"d4d60711e9346d0b52737a2b84f61b8a","volatility":"v"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_ATTRS' USING ERRCODE='40001';END IF;
 IF ((heads->'mission_generic_owner.unified_director_commit(uuid,jsonb)')->>'oid'='51131') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_OID' USING ERRCODE='40001';END IF;
 IF (((heads->'mission_generic_owner.unified_batch_payload(uuid)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":true,"signature":"mission_generic_owner.unified_batch_payload(uuid)","source_md5":"b877c563d0ed3424ca5f3d796679eac8","volatility":"v"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_ATTRS' USING ERRCODE='40001';END IF;
 IF ((heads->'mission_generic_owner.unified_batch_payload(uuid)')->>'oid'='51125') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_OID' USING ERRCODE='40001';END IF;
 IF (((heads->'public.mission_generic_counted_resume_v1(uuid,jsonb)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres,service_role=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":true,"signature":"public.mission_generic_counted_resume_v1(uuid,jsonb)","source_md5":"bdf99e6a0507036084719f6f04aeba18","volatility":"v"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_ATTRS' USING ERRCODE='40001';END IF;
 IF ((heads->'public.mission_generic_counted_resume_v1(uuid,jsonb)')->>'oid'='325803') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_OID' USING ERRCODE='40001';END IF;
 IF (((heads->'mission_generic_owner.staff_journal_settlements_v1(uuid,uuid)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":false,"signature":"mission_generic_owner.staff_journal_settlements_v1(uuid,uuid)","source_md5":"66f14ed757194cd8c82243ae38b9bd53","volatility":"s"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_ATTRS' USING ERRCODE='40001';END IF;
 IF ((heads->'mission_generic_owner.staff_journal_settlements_v1(uuid,uuid)')->>'oid'='341329') IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST10X_OID' USING ERRCODE='40001';END IF;
